\label{ass:technical}
We require that both:

\begin{enumerate}
\item
    $\operatorname{\mathrm{\Delta}}_u U(u) \leq M + \dfrac \alpha 2 |\nabla_u U(u)|^2$
    for some $M \geq 1$ and $\alpha \in (0, 1)$, both \emph{possibly dependent} on $\delta$.
\item
    The embeddings $H^1(\mu_\delta) \hookrightarrow L^2(\mu_\delta)$ are compact for all $\delta > 0$.
\end{enumerate}

\label{thm:clw 2.1}
Since $\sigma_{p} \geq \sigma$, Assumption~\ref{ass:log-sobolev}
implies that we have the following tensorised Poincaré inequality
for $g\in H^1(\tau \otimes \mu_\delta)$:
\[
\|g - {\textstyle\int g \mathop{}\!\mathrm d(\tau \otimes \mu)}\|_{L^2(\tau \otimes \mu)}^2
\leq \max\!\left\{ \frac{1}{\delta^{d}\sigma_{p}}, \frac{T^2}{\pi^2} \right\}
    \left( \|\partial_t g\|_{L^2(\tau \otimes \mu)}^2
        + \|\nabla_u g\|_{L^2(\tau \otimes \mu)}^2 \right).
\]

We only prove the second statement, the first is proved analogously.
As in \cite[Eq.~(20)]{cao_explicit_2023}, we start from the following Bochner identity,
also known as the $\Gamma_2$ identity \cite[Section~1.16]{bakry_analysis_2014}:
\begin{equation}\label{eq:clw 2.3 beginning}
\begin{split}
\|\nabla_u^2 g\|_{L^2(\tau \otimes \mu)}^2
&= \sum_{x,y \in \Lambda} \iint |\partial_{u(x)} \partial_{u(y)} g(u)|^2 \mathop{}\!\mathrm d\mu_\delta(u) \mathop{}\!\mathrm d\tau(t)\\
&= \|\nabla_u^\ast \nabla_u g\|_{L^2(\tau \otimes \mu)}^2\\
&\qquad -\iint
    (\nabla_u g(t,u))^\top (\nabla_u^2 U(u)) (\nabla_u g(t,u)) \mathop{}\!\mathrm d\mu_\delta(u) \mathop{}\!\mathrm d\tau(t).
\end{split}
\end{equation}
We estimate the second term from above.
By computing the Hessian of the energy $U$, we find that the second term equals
\begin{equation}
-\iint \delta^d \sum_{x \in \Lambda} \Bigl[ (V''(u(x)) + m^2) (\partial_{u(x)} g(t,u))^2
        + |\nabla_\delta \partial_{u(x)} g(t,u)|^2 \Bigr]
    \mathop{}\!\mathrm d\mu_\delta(u) \mathop{}\!\mathrm d\tau(t).
\end{equation}
We now decompose $h(x)^2 \coloneqq \partial_{u(x)} g(t,u)^2$ as $\sum_{i\in \mathbb Z^d} h_i^2$
given by $h_i=\partial_{u(x)} g(t,u) \chi_{i}$,
where $\chi^{2}_i$ is a suitable partition of unity supported on $B(i,2)$ for $i\in \mathbb Z^d$.
We will also require a family $\tilde{\chi}_i$ of smooth cutoff functions supported in $B(i,4)$
and equal to $1$ on the support of $\chi_i$,
such that $\sum_{i\in \mathbb Z^d} \tilde{\chi}^2_i = 2^d$.
Then we can write the above expression as 
\begin{equation}
-\sum_{i \in \mathbb Z^d}\iint \delta^d \sum_{x \in \Lambda} \Bigl[ V''(u(x)) h_i^2
        + m^2 h_i^2 + |\chi_i \nabla_\delta h|^2 \Bigr]
    \mathop{}\!\mathrm d\mu_\delta(u) \mathop{}\!\mathrm d\tau(t).
\end{equation}
We may write
\begin{equation}
\chi_i \nabla_\delta h
= \chi_i \nabla_\delta (\tilde\chi_i h)
= \nabla (\chi_i \tilde\chi_i h) - (\nabla \chi_i) \tilde\chi_i h
= \nabla (\chi_i h) - (\nabla \chi_i) \tilde\chi_i h.
\end{equation}
Therefore we can estimate with Young's inequality
\begin{equation}
-|\chi_i \nabla_\delta h|^2
\leq -\frac 1 2 |\nabla_\delta (\chi_i h)|^2
    + |(\nabla \chi_i) \tilde\chi_i h|^2.
\end{equation}
By construction $|\nabla \chi_i| \leq C$ for some uniform, dimension-dependent constant.
Therefore
\begin{equation}
\begin{split}
&\mathrel{\phantom{=}}
-\iint \delta^d \sum_{x \in \Lambda} \Bigl[ V''(u(x)) h_i(x)^2 + m^2 h_i(x)^2
        + | \chi_i \nabla_\delta h|^2 \Bigr]
    \mathop{}\!\mathrm d\mu_\delta(u) \mathop{}\!\mathrm d\tau(t)\\
&\leq -\iint \delta^d \sum_{x \in \Lambda} \Bigl[ V''(u(x)) h_i(x)^2 + m^2 h_i(x)^2
        + \frac{1}{2}| \nabla_\delta h_i|^2 \Bigr] + C \delta^d \sum_{x \in \Lambda} \tilde{\chi}^{2}_{i}  h^2 \mathop{}\!\mathrm d\mu_\delta(u) \mathop{}\!\mathrm d\tau(t).
\end{split}
\end{equation}
Now by Assumption~\ref{ass:potential-intro} this can be bounded by
\begin{equation}\label{eq:clw 2.3 sum}
\sum_{x \in \Lambda} \delta^d \iint (Q_i(u)) (h_i)^2 
    \mathop{}\!\mathrm d\mu_\delta(u) \mathop{}\!\mathrm d\tau(t) + C \delta^d \sum_{x \in \Lambda} \tilde{\chi}^{2}_{i}  h^2 \mathop{}\!\mathrm d\mu_\delta(u) \mathop{}\!\mathrm d\tau(t)
\end{equation}
Now by Lemma~\ref{thm:ngs bound} (taking $\psi(u) = 2 Q(u)$ and $f(u) = 2^{-1/2} h_i(x)$
with $x$ and $i$ fixed)
and $R^2$ from Assumption~\ref{ass:potential-intro}, the integral is bounded by
\begin{equation}
\int \Bigl[ \delta^d R^2 \int
        (h_i(t,x,u))^2 \mathop{}\!\mathrm d\mu_\delta(u)
    + \frac 1 2 \int |\nabla_u h_i(t,x,u)|^2 \mathop{}\!\mathrm d\mu_\delta(u) \Bigr] \mathop{}\!\mathrm d\tau(t)+C \delta^d \sum_{x \in \Lambda} \tilde{\chi}^{2}_{i}  h^2 \mathop{}\!\mathrm d\mu_\delta(u) \mathop{}\!\mathrm d\tau(t)
\end{equation}
Summing over $x \in \Lambda$ and $i\in \mathbb Z^d$ we obtain 
\begin{equation}
\begin{split}
&\mathrel{\phantom{=}}
    \|\nabla_u^2 g\|_{L^2(\tau \otimes \mu)}^2\\
&\leq \|\nabla_u^\ast \nabla_u g\|_{L^2(\tau \otimes \mu)}^2
    + \delta^d (R^2+2^d C) \iint |\nabla_u g(t,u)|^2 \mathop{}\!\mathrm d\mu_\delta(u) \mathop{}\!\mathrm d\tau(t)
    + \frac{1}{2} \|\nabla_u^2 g\|_{L^2(\tau \otimes \mu)}^{2}.
\end{split}
\end{equation}
Subtraction of the last term on the right-hand side gives the desired bound. 
Under Assumption~\ref{ass:hessian finite} the proof proceeds
without using the partition of unity,
which removes the $2^d C$~term on the right-hand side.

The gradient of $Q(u)$ is well-defined by Kato perturbation theory.
Indeed Q is the bottom eigenvalue of a discrete Schrödinger operator,
which is known to be simple by comparison principle,
so Kato perturbation theory implies that $Q$ is smooth if $V$ depends smoothly on $u$~\cite[Chapter~2]{kato_1996}. 
For any $v \in L^2(\Lambda)$ and $t > 0$,
we can plug $\psi^u$ into both infima to estimate
\begin{equation}
\begin{split}
&\mathrel{\phantom{=}} \frac{1}{t} \inf_{\|\psi\|_{L^2(\Lambda)} = 1}
    \left( \sum_{x \in\Lambda} \chi V'' (u + t v) \psi^2
        + \frac 1 2 |\nabla_\delta \psi|^2
        + m^2 \psi^2  \right)\\
&\qquad - \frac{1}{t} \inf_{\|\psi\|_{L^2(\Lambda)} = 1}
    \left( \sum_{x \in\Lambda} \chi V'' (u) \psi^2
        + \frac 1 2 |\nabla_\delta \psi|^2
        + m^2 \psi^2   \right)\\
&\leq \frac{1}{t} \left( \sum_{x \in\Lambda} \chi V''(u + t v) (\psi^u)^2 
    - \sum_{x \in\Lambda} \chi V''(u) (\psi^u)^2  \right)\\
&\to \sum_{x \in\Lambda} \chi V'''(u)(\psi^u)^2 v
\end{split}
\end{equation}
in the $t \to 0$ limit.
We obtain the converse inequality by replacing $v$ with $-v$.
Therefore
\begin{equation}
-\langle \nabla_u Q (u), v \rangle_{L^2 (\Lambda)}
= \langle \chi V''' (u) (\psi^u)^2, v \rangle_{L^2 (\Lambda)},
\end{equation}
from which the statement follows by duality.

\label{lem:estimate-psi-phi42}
The following estimate holds:
\begin{equation}
\begin{split}
\|\psi^{W+I}\|_{H^1(\Lambda)}^2
&\leq C_\varepsilon \lambda
    \left(
      1+\|\chi \mathord{\mathopen: W^2 \mathclose:}\|_{\mathcal C^{-\varepsilon}(\Lambda)}
       +\|\chi^{1/2}W\|_{\mathcal C^{-\varepsilon}(\Lambda)}
        \|\chi^{1/2}I\|_{H^{1}(\Lambda)}
    \right)^{1/(1-\varepsilon)}\\
&\quad + 2 \lambda\|\chi^{1/2}I\|_{L^2(\Lambda)}^2 + 2.
\end{split}
\end{equation}

Let $\psi=\psi^{W+I}$ be as in Lemma~\ref{lem:Grad-bottom},
minimizing the quadratic form
\begin{equation}\label{eq:estimate-psi-phi42 qf}
12 \lambda \delta^2 \sum_{x\in\Lambda}\chi \mathord{\mathopen: (W+I)^2 \mathclose:}\psi^2
    + \frac 1 2 \|\nabla_\delta \psi\|_{L^2}^2
    + m^2 \|\psi\|_{L^2}^2.
\end{equation}
Since $\|\psi\|_{L^2}^2=1$ by assumption,
\begin{equation}
\|\nabla_\delta \psi\|_{L^2}^2
= \|\psi\|_{H^1}^2 - 1.
\end{equation}
Moreover by duality and interpolation,
\begin{equation}\label{eq:estimate-psi-phi42 w terms}
\begin{split}
&\mathrel{\phantom{=}}
    12\lambda \delta^2 \left|\sum_{x\in\Lambda}\chi \mathord{\mathopen: W^2 \mathclose:} \psi^2\right|
    + 24\lambda \delta^2 \left|\sum_{x\in\Lambda}\chi WI\psi^2\right|\\
&\leq C\lambda
    \left(\|\chi \mathord{\mathopen: W^2 \mathclose:}\|_{\mathcal C^{-\varepsilon}}
        + \|\chi^{1/2}W\|_{\mathcal C^{-\varepsilon}}\|\chi^{1/2}I\|_{H^{1}} \right)
    \|\psi\|_{H^\varepsilon}^2.
\end{split}
\end{equation}
Let us set
\begin{equation}
A(W,I) = 1 + \|\chi \mathord{\mathopen: W^2 \mathclose:}\|_{\mathcal C^{-\varepsilon}}
    + \|\chi^{1/2}W\|_{\mathcal C^{-\varepsilon}}
      \|\chi^{1/2}I\|_{H^{1}}.
\end{equation}
Therefore by Young's inequality
\begin{equation}
\begin{split}
\eqref{eq:estimate-psi-phi42 w terms}
&\leq C\lambda A(W,I) \|\psi\|_{H^1}^{2\varepsilon}\\
&\leq \frac{1}{4} \|\psi\|_{H^1}^2
    + C_\varepsilon \lambda^{1/(1-\varepsilon)} A(W,I)^{1/(1-\varepsilon)},
\end{split}
\end{equation}
and we get the lower bound
\begin{equation}
\eqref{eq:estimate-psi-phi42 qf}
\geq \frac{1}{4} \|\psi\|_{H^1}^2
    - C_\varepsilon \lambda^{1/(1-\varepsilon)} A(W,I)^{1/(1-\varepsilon)}
    - 1 + m^2.
\end{equation}

At the same time we can bound~\eqref{eq:estimate-psi-phi42 qf} from above
by plugging some fixed $\psi = \psi_0$ into the quadratic form.
Let us choose $\psi_0 = |\mathbb T^2|^{-1/2}$.
Then $\|\psi_0\|_{L^2(\Lambda)} = 1$ and $\psi_0 \leq 1$, so
\begin{equation}
\begin{split}
&\mathrel{\phantom{=}}
    12 \lambda \delta^2 \sum_{x \in \Lambda} \chi \mathord{\mathopen: (W + I)^2 \mathclose:} \psi_0^2
    + \frac 1 2 \|\nabla_\delta \psi_0\|_{L^2}^2
    + m^2 \|\psi_0\|_{L^2}^2\\
&= \frac{\lambda \delta^2}{|\mathbb T^2|} \sum_{x \in \Lambda} \chi \mathord{\mathopen: (W + I)^2 \mathclose:} + m^2\\
&\leq \lambda \|\chi \mathord{\mathopen: W^2 \mathclose:}\|_{\mathcal C^{- \varepsilon}}
    + C\lambda \|\chi^{1 / 2} W\|_{\mathcal C^{- \varepsilon}}
        \|\chi^{1 / 2} I\|_{H^{\varepsilon}}
    + \lambda \|\chi^{1 / 2} I\|^2_{L^2}
    + m^2\\
&\leq C\lambda A(W,I) + \lambda \|\chi^{1/2}I\|_{L^2}^2 + m^2.
\end{split}
\end{equation}
Here we expanded the Wick power and used duality.
Combining these two estimates gives
\begin{equation}
\frac{1}{4} \|\psi\|_{H^1}^2
\leq C\lambda A(W,I) + C_\varepsilon \lambda^{1/(1-\varepsilon)} A(W,I)^{1/(1-\varepsilon)}
    + \lambda \|\chi^{1/2}I\|_{L^2}^2 + 1.
\end{equation}
Since $A(W,I) \geq 1$ and $\lambda \leq 1$, this yields the statement.

We begin by observing that
$q \lambda \int \chi(\psi^{W+I})^2 I^2 \mathop{}\!\mathrm d x \geq 0$.
We now estimate the
remaining term
\begin{equation}\label{eq:estimate-product-WI}
\begin{split}
&\mathrel{\phantom{=}} q\lambda\left|\delta^2 \sum_{x \in \Lambda}
    \chi(\psi^{W+I})^2WI\right|\\
                 
                                            
                                                                 
&\leq C q\lambda  \|W\|_{\mathcal C^{-\varepsilon}(\rho)}
    \|\chi(\psi^{W+I})\|^{2}_{H^{\varepsilon}(\Lambda)} \|I\|_{H^{1}(\rho^{1/2})}\\
&\leq C q\lambda  \|W\|_{\mathcal C^{-\varepsilon}(\rho)} \left[
    \lambda \left(1+\|\chi \mathord{\mathopen: W^2 \mathclose:}\|_{\mathcal C^{-\varepsilon}}
        +\|\chi^{1/2} W\|_{\mathcal C^{-\varepsilon}} \|\chi^{1/2}I\|_{H^{1}}
    \right)^{1/(1-\varepsilon)} \right.\\
&\hspace{8em} \left.{} + 2\lambda\|\chi^{1/2}I\|_{L^2}^2 + 2 \right]^{2\varepsilon}
        \|I\|_{H^{1}(\rho^{1/2})} .
\end{split}
\end{equation}
In the last line we used Lemma~\ref{lem:estimate-psi-phi42} and Besov interpolation.
To continue the estimate, set
\begin{equation}
    X=\|I\|_{H^1(\rho)},\qquad
    \alpha=\frac{2\varepsilon}{1-\varepsilon}.
\end{equation}
Using concavity of $x\mapsto x^{2\varepsilon}$ and the bound
$\|\chi^{1/2}I\|_{L^2(\Lambda)}+ \|\chi^{1/2}I\|_{H^1(\Lambda)}\lesssim X$,
equation~\eqref{eq:estimate-product-WI} is bounded by
\begin{equation}
Cq\lambda \|W\|_{\mathcal C^{-\varepsilon}(\rho)}
\left[
    \lambda^{2\varepsilon}
        \!\left(1 +\|\chi \mathord{\mathopen: W^2 \mathclose:}\|_{\mathcal C^{-\varepsilon}(\rho)}^\alpha \right)\! X
    + \lambda^{2\varepsilon} \|\chi^{1/2} W\|_{\mathcal C^{-\varepsilon}(\rho)}^\alpha X^{1+\alpha}
    + \lambda^{2\varepsilon} X^{1+4\varepsilon}
    + X
\right]\!.
\end{equation}
We extract~$X^2$ from each term with Young's inequality (which requires $\varepsilon<1/4$).
This gives
\begin{equation}
\begin{split}
&\mathbin{\phantom{+}}
    C_\kappa q^2 \lambda^{2+4\varepsilon} \|W\|_{\mathcal C^{-\varepsilon}(\rho)}^2
    \!\left(1 +\|\chi \mathord{\mathopen: W^2 \mathclose:}\|_{\mathcal C^{-\varepsilon}(\rho)}^\alpha \right)^2\\
&+ C_\kappa q^{2/(1-\alpha)} \lambda^{2(1+2\varepsilon)/(1-\alpha)}
    \|W\|_{\mathcal C^{-\varepsilon}(\rho)}^{2/(1-\alpha)}
    \|\chi^{1/2} W\|_{\mathcal C^{-\varepsilon}(\rho)}^{2\alpha/(1-\alpha)}\\
&+ C_\kappa q^{2/(1-4\varepsilon)} \lambda^{2(1+2\varepsilon)/(1-4\varepsilon)}
    \|W\|_{\mathcal C^{-\varepsilon}(\rho)}^{2/(1-4\varepsilon)}\\
&+ C_\kappa q^2 \lambda^2 \|W\|_{\mathcal C^{-\varepsilon}(\rho)}^2\\
&+ \kappa m^2 X^2.
\end{split}
\end{equation}
This is the decomposition in the statement.
To compute expectations of the stochastic terms, we use Lemma~\ref{wick-power-estimate}.
It gives $p$ dependent on $\varepsilon$ such that
each expectation is at most $C_\varepsilon (1 + |\log(m)|^{p})$.
Hence $\mathord{\mathbb E} |\mathcal{G}_{q,\lambda,m,\varepsilon,\kappa}(W)|$ is bounded by
\begin{equation}
C_{\kappa,\varepsilon} \left[
    q^2 \lambda^{2+4\varepsilon}
    + q^{2/(1-\alpha)} \lambda^{2(1+2\varepsilon)/(1-\alpha)}
    + q^{2/(1-4\varepsilon)} \lambda^{2(1+2\varepsilon)/(1-4\varepsilon)}
    + q^2 \lambda^2
\right] (1 + |\log(m)|^{p}).
\end{equation}
Under the assumption $\lambda \leq 1$ we may use $1-\alpha \leq 1$
to further simplify this expression.

\label{Lem:coercive}
For any $p \geq 8$, there exists $C<\infty$ such that
\begin{equation}\label{eq:coercive-with-mass-shift}
\begin{split}
&\mathrel{\phantom{=}}
    4\lambda \delta^2 \sum_{x \in \Lambda} \rho \mathord{\mathopen: (W + I)^3 \mathclose:} I
    - 2(1-m^2) \delta^2 \sum_{x \in \Lambda} \rho (W+I) I\\
&\geq 
    3\lambda \|I\|^4_{L^4 (\rho^{1/4})}
    - m^2 \|I\|^2_{H^1 (\rho^{1/2})}
    - C\frac{(1-m^2)^2}{\lambda} \|\rho\|_{L^1(\Lambda)}\\
&\qquad - C \bigg(\frac{\lambda^2}{m^2}
        + \frac{\lambda^3}{m^4}
        + \frac{(1-m^2)^4}{m^2}\bigg)
    \!\bigg(1 + \sum_{i = 1}^3 \|\mathord{\mathopen: W^i \mathclose:}\|_{\mathcal C^{-\varepsilon}(\rho^{1/8})}^p\bigg).
\end{split}
\end{equation}

By the Wick binomial formula,
\begin{equation}
    4\mathord{\mathopen: (W + I)^3 \mathclose:} I = 4I^4 + 12 W I^3 + 12 \mathord{\mathopen: W^2 \mathclose:} I^2 + 4 \mathord{\mathopen: W^3 \mathclose:} I .
\end{equation}
The first term gives $4 \lambda \|I\|_{L^4(\rho^{1/4})}^4$.
The three mixed terms match the last three terms
in the proof of~\cite[Lemma~21]{barashkov_variational_2023}.
By duality and the weighted product estimates, for $\varepsilon>0$ small enough,
\begin{equation}
\begin{split}
\left|\delta^2 \sum_{x \in \Lambda} \rho \mathord{\mathopen: W^3 \mathclose:} I \mathop{}\!\mathrm d x\right|
    &\leq C \|\mathord{\mathopen: W^3 \mathclose:}\|_{\mathcal C^{-\varepsilon}(\rho^{1/8})}
        \|I\|_{H^1(\rho^{1/2})},\\
\left|\delta^2 \sum_{x \in \Lambda} \rho \mathord{\mathopen: W^2 \mathclose:} I^2 \mathop{}\!\mathrm d x\right|
    &\leq C \|\mathord{\mathopen: W^2 \mathclose:}\|_{\mathcal C^{-\varepsilon}(\rho^{1/8})}
        \|I\|_{L^4(\rho^{1/4})} \|I\|_{H^1(\rho^{1/2})},\\
\left|\delta^2 \sum_{x \in \Lambda} \rho W I^3 \mathop{}\!\mathrm d x\right|
    &\leq C \|W\|_{\mathcal C^{-\varepsilon}(\rho^{1/8})}
        \|I\|_{H^1(\rho^{1/2})}^{1/2}
        \|I\|_{L^4(\rho^{1/4})}^{5/2}.
\end{split}
\end{equation}
Applying Young's inequality with the weights
$\lambda\|I\|_{L^4(\rho^{1/4})}^4$ and
$m^2\|I\|_{H^1(\rho^{1/2})}^2$ gives
\begin{equation}
\begin{split}
\lambda \|\mathord{\mathopen: W^3 \mathclose:}\|_{\mathcal C^{-\varepsilon}(\rho^{1/8})}
        \|I\|_{H^1(\rho^{1/2})}
    &\leq \frac{m^2}{4}\|I\|_{H^1(\rho^{1/2})}^2
        + C\frac{\lambda^2}{m^2}
        \|\mathord{\mathopen: W^3 \mathclose:}\|_{\mathcal C^{-\varepsilon}(\rho^{1/8})}^2,\\
\lambda \|\mathord{\mathopen: W^2 \mathclose:}\|_{\mathcal C^{-\varepsilon}(\rho^{1/8})}
        \|I\|_{L^4(\rho^{1/4})} \|I\|_{H^1(\rho^{1/2})}
    &\leq \frac{\lambda}{4}\|I\|_{L^4(\rho^{1/4})}^4
        + \frac{m^2}{4}\|I\|_{H^1(\rho^{1/2})}^2
        + C\frac{\lambda^3}{m^4}
        \|\mathord{\mathopen: W^2 \mathclose:}\|_{\mathcal C^{-\varepsilon}(\rho^{1/8})}^4,\\
\lambda \|W\|_{\mathcal C^{-\varepsilon}(\rho^{1/8})}
        \|I\|_{H^1(\rho^{1/2})}^{1/2}
        \|I\|_{L^4(\rho^{1/4})}^{5/2}
    &\leq \frac{\lambda}{4}\|I\|_{L^4(\rho^{1/4})}^4
        + \frac{m^2}{4}\|I\|_{H^1(\rho^{1/2})}^2
        + C\frac{\lambda^3}{m^4}
        \|W\|_{\mathcal C^{-\varepsilon}(\rho^{1/8})}^8.
\end{split}
\end{equation}
It remains to bound the quadratic term of the statement.
For the mixed linear term, duality and Young's inequality give
\begin{equation}
\begin{split}
(1-m^2) \left|\delta^2 \sum_{x\in\Lambda}\rho W I\right|
&\leq C (1-m^2) \|W\|_{\mathcal C^{-\varepsilon}(\rho^{1/2})}
    \|I\|_{H^1(\rho^{1/2})}\\
&\leq \frac{m^2}{4} \|I\|_{H^1(\rho^{1/2})}^2
    + \frac{C(1-m^2)^4}{m^2} \|W\|^{4}_{\mathcal C^{-\varepsilon}(\rho^{1/8})} .
\end{split}
\end{equation}
For the quadratic we use the pointwise estimate
\begin{equation}
    (1-m^2)\,|I|^2
    \leq \frac{\lambda}{2} |I|^4
        + C\frac{(1-m^2)^2}{\lambda},
\end{equation}
which after multiplying by $\rho$ and summing yields
\begin{equation}
    -(1-m^2)\delta^2 \sum_{x\in\Lambda}\rho I^2
    \geq -\frac{\lambda}{2}\|I\|_{L^4(\rho^{1/4})}^4
        -C\frac{(1-m^2)^2}{\lambda} \|\rho\|_{L^1(\Lambda)}.
\end{equation}
The previous mixed cubic estimates used only $\lambda/2$ of the leading
quartic term and $3m^2/4$ of the $H^1$ term. The two estimates above use
another $\lambda/2$ and $m^2/4$, leaving precisely the coercive terms displayed
in~\eqref{eq:coercive-with-mass-shift}. Choosing $p \geq 8$ and using
$a^2+a^4+a^8 \leq C(1+a^p)$ completes the proof.

\label{lemma:apriori}
For some $C$, $p<\infty$ independent of $\lambda$, $m$, $q$, and~$\delta$,
we have
\[
    3\lambda \mathord{\mathbb E}_{\zeta^Q}
      \|I\|^4_{L^4(\rho^{1/4})}
    + (1 - (1+\kappa) m^2)\mathord{\mathbb E}_{\zeta^Q}
      \|I\|^2_{H^1(\rho^{1/2})}
    \leq C\mathcal{B}_{q,\lambda,m,\varepsilon},
\]
where
\[
\mathcal{B}_{q,\lambda,m,\varepsilon}
\coloneqq
\bigg(\lambda^2 q^2 + \lambda^2 q^{2/(1-4\varepsilon)}
    + \frac{\lambda^2}{m^2}
    + \frac{\lambda^3}{m^4}
    + \frac{(1-m^2)^4}{m^2}\bigg) (1 + |\log(m)|^{p})
+ \frac{(1-m^2)^2}{\lambda} \|\rho\|_{L^1(\Lambda)}
\]
when $\lambda \leq m < 1$.

Recalling \eqref{eq:EL-phi42},
\begin{equation}\label{eq:EL-phi42-repeat}
\begin{split}
0
&= \mathord{\mathbb E}_{\zeta^Q} \left[
    24 \lambda q \delta^2 \sum_{x \in \Lambda}
        \rho \chi (\psi^{W + I})^2 (W + I) I
    + 4\lambda \delta^2 \sum_{x \in \Lambda}
        \rho \mathord{\mathopen: (W + I)^3 \mathclose:} I \right.\\
&\hspace{5em}\left.
    - 2(1-m^2) \delta^2 \sum_{x \in \Lambda}\rho(W+I)I
    + \int_0^1 \delta^2 \sum_{x \in \Lambda}
        \rho \left[ |\nabla_{\delta}\dot{I}_s|^2 + \dot{I}_s^2 \right] \mathop{}\!\mathrm d s
    \right]\\
&\quad + \mathord{\mathbb E}_{\zeta^Q}
    \int_0^1 \delta^2 \sum_{x\in \Lambda}
        ([\rho,\nabla_{\delta}]\dot{I}_s) \nabla_{\delta}\dot{I}_s
        \mathop{}\!\mathrm d s.
\end{split}
\end{equation}
Let us first fix the weight.
Since $\rho(x)=(1+ K_2|x|^2)^{-K_1/2}$, we can estimate for example
\begin{equation}
|\partial_{x_i} \rho(x)|
= \left|K_1 K_2 \rho(x) \frac{x_i}{1 + K_2 |x|^2}\right|
\leq K_1 K_2^{1/2} |\rho(x)|.
\end{equation}
We can therefore choose $K_2 > 0$ to be small enough (dependent on $K_1$) that
\begin{equation}\label{eq:weight derivative}
    |\nabla_{\delta}\rho(x)|
    \leq \frac 3 2 |\rho(x)|
\end{equation}
uniformly in $\delta \lesssim 1$.
Hence by Cauchy--Schwarz
\begin{equation}
\left|\delta^2 \sum_{x\in\Lambda}
    ([\rho,\nabla_\delta]\dot{I})(x)\nabla_\delta \dot{I}(x)\right|
\leq \frac{3\delta^2}{4} \sum_{x\in\Lambda}\rho(x) |\nabla_\delta \dot{I}(x)|^2
    + \frac{3\delta^2}{4} \sum_{x\in\Lambda}\rho(x) \dot{I}(x)^2 .
    \label{eq:weight-commutator}
\end{equation}
Taking~$\varepsilon$ sufficiently small, we therefore have
\begin{equation}
\int_{0}^1 \delta^2 \sum_{x\in \Lambda} \bigl[ ([\rho,\nabla_{\delta}]\dot I_s)\nabla_\delta \dot I_{s}
    + \rho|\nabla_{\delta}\dot I_s|^2+ \rho \dot{I}_s^2 \bigr] \mathop{}\!\mathrm d s
\geq \frac{1}{4} \int_0^1 \delta^2 \sum_{x \in \Lambda}
    \rho \bigl[ |\nabla_{\delta}\dot I_s|^2 + \dot{I}_s^2 \bigr] \mathop{}\!\mathrm d s.
\end{equation}
Then by Jensen's inequality we may bound
\begin{equation}
\int_0^1 \delta^2 \sum_{x \in \Lambda}
    \rho \bigl[ |\nabla_{\delta}\dot I_s|^2+ \dot{I}_s^2 \bigr] \mathop{}\!\mathrm d s
\geq \|I_{1}\|_{H^1(\rho^{1/2})}^2.
\end{equation}
Therefore the last two terms of~\eqref{eq:EL-phi42-repeat}
can be controlled with $\|I\|_{H^1(\rho^{1/2})}$.
Now the first term of~\eqref{eq:EL-phi42-repeat}
is estimated by Lemma~\ref{Lem:gradient-quadratic-form} as
\begin{equation}
24 \lambda q \delta^2 \mathord{\mathbb E} \sum_{x \in \Lambda} \chi(\psi^{W+I})^2(W+I)I
                                                         
                                                   
\geq -C_{\kappa,\varepsilon} \lambda^2 \left[ q^2 + q^{2/(1-4\varepsilon)}\right]
        (1 + |\log(m)|^{p})
    -\kappa m^2 \mathord{\mathbb E} \|I\|^2_{H^{1}(\rho^{1/2})},
\end{equation}
and the next two terms by Lemma~\ref{Lem:coercive} and Lemma~\ref{wick-power-estimate} as
\begin{equation}
\begin{split}
&\mathrel{\phantom{=}}
    4\lambda \delta^2 \mathord{\mathbb E} \sum_{x \in \Lambda} \rho \mathord{\mathopen: (W + I)^3 \mathclose:} I
    - 2(1-m^2) \delta^2 \mathord{\mathbb E} \sum_{x \in \Lambda} \rho (W+I) I\\
&\geq 
    3\lambda \mathord{\mathbb E} \|I\|^4_{L^4 (\rho^{1/4})}
    - m^2 \mathord{\mathbb E} \|I\|^2_{H^1 (\rho^{1/2})}
    - C\frac{(1-m^2)^2}{\lambda} \|\rho\|_{L^1(\Lambda)}\\
&\qquad - C \bigg(\frac{\lambda^2}{m^2}
        + \frac{\lambda^3}{m^4}
        + \frac{(1-m^2)^4}{m^2}\bigg) (1 + |\log(m)|^{p})
\end{split}
\end{equation}
for some sufficiently large~$p$.
Therefore we have shown
\begin{equation}
0 \geq 3\lambda \|I\|_{L^4(\rho^{1/4})}^4
    + (1 - \kappa m^2 - m^2) \mathord{\mathbb E} \|I\|_{H^1(\rho^{1/2})}^2
    - C \mathcal{B}_{q,\lambda,m,\varepsilon},
\end{equation}
which implies the claim once $\kappa$ is taken small enough.

It suffices to estimate the two terms on the right-hand side of~\eqref{eq:lower-bound-Q} from below.
Duality and interpolation give
\begin{equation}
\lambda q \left|\delta^2 \sum_{x\in\Lambda}\chi \mathord{\mathopen: W^2 \mathclose:}(\psi^{W+I})^2\right|
\geq -C_\varepsilon\lambda q 
    \|\chi \mathord{\mathopen: W^2 \mathclose:}\|_{\mathcal C^{-\varepsilon}(\rho)}
    \|\psi^{W+I}\|_{H^1(\Lambda)}^{2\varepsilon}.
\end{equation}
Applying Lemma~\ref{lem:estimate-psi-phi42}, we get
\begin{equation}\label{eq:W2-psi-bound}
\begin{split}
&\mathrel{\phantom{=}} \lambda q
    \|\chi \mathord{\mathopen: W^2 \mathclose:}\|_{\mathcal C^{-\varepsilon}(\rho)}
    \|\psi^{W+I}\|_{H^1}^{2\varepsilon}\\
&\leq C_\varepsilon \lambda q
    \|\chi \mathord{\mathopen: W^2 \mathclose:}\|_{\mathcal C^{-\varepsilon}(\rho)}
    \Bigl[\lambda
    \left(
      1+\|\mathord{\mathopen: W^2 \mathclose:}\|_{\mathcal C^{-\varepsilon}(\rho)}
       +\|W\|_{\mathcal C^{-\varepsilon}(\rho)}
        \|I\|_{H^{1}(\rho^{1/2})}
    \right)^{1/(1-\varepsilon)}\\
&\hspace{10em} {} + 2 \lambda\|I\|_{L^2(\rho^{1/2})}^2 + 2\Bigr]^{\varepsilon}.
\end{split}
\end{equation}
Using the concavity of $x\mapsto x^\varepsilon$ and Hölder's inequality
(again assuming $\lambda \leq 1$),
the expectation of this is bounded by
\begin{equation}
\begin{split}
&C_\varepsilon \lambda q \left[\mathord{\mathbb E}_{\zeta^Q} \|\chi \mathord{\mathopen: W^2 \mathclose:}\|_{\mathcal C^{-\varepsilon}(\rho)}^2 \right]^{1/2}\\
&\quad
    \left[ 1
        + \mathord{\mathbb E}_{\zeta^Q} \|\mathord{\mathopen: W^2 \mathclose:}\|_{\mathcal C^{-\varepsilon}(\rho)}^{2\varepsilon/(1-\varepsilon)}
        + \left( \mathord{\mathbb E}_{\zeta^Q} \|W\|_{\mathcal C^{-\varepsilon}(\rho)}^{4\varepsilon/(1-\varepsilon)}
            \mathord{\mathbb E}_{\zeta^Q} \|I\|_{H^1(\rho^{1/2})}^{4\varepsilon/(1-\varepsilon)} \right)^{1/2}
        + 2 \mathord{\mathbb E}_{\zeta^Q} \|I\|_{H^1(\rho^{1/2})}^{2\varepsilon}
    \right]^{1/2}.
\end{split}
\end{equation}
By Lemmas~\ref{lemma:apriori} and~\ref{wick-power-estimate},
there exists $p<\infty$ such that this is bounded by
\begin{equation}
C_\varepsilon \lambda q (1 + |\log m|^p) \!
    \left[ 1
    + \left(\frac{\mathcal B_{q,\lambda,m,\varepsilon}}{(1 - (1+\kappa) m^2)}\right)^{\varepsilon/2(1-\varepsilon)}
    + \left(\frac{\mathcal B_{q,\lambda,m,\varepsilon}}{(1 - (1+\kappa) m^2)}\right)^{\varepsilon/2}
    \right].
\end{equation}
Since $\varepsilon$ is small, we can neglect the final term of the bracket.

In the cross term we can estimate by Besov product estimates, interpolation, and Hölder
\begin{equation}
\begin{split}
\lambda q \mathord{\mathbb E} \left|\delta^2 \sum_{x\in\Lambda}\chi W I(\psi^{W+I})^2\right|
&\leq C_\varepsilon \lambda q \|W\|_{\mathcal C^{-\varepsilon}(\rho)}
    \|\psi^{W+I}\|_{H^{2\varepsilon}(\Lambda)}
    \|I\|_{H^1(\rho^{1/2})}\\
&\leq C_\varepsilon \lambda q \|W\|_{\mathcal C^{-\varepsilon}(\rho)}
    \|\psi^{W+I}\|_{H^1(\Lambda)}^{2\varepsilon}
    \|I\|_{H^1(\rho^{1/2})}\\
&\leq C_\varepsilon \lambda q \left[
    \mathord{\mathbb E} \|W\|_{\mathcal C^{-\varepsilon}(\rho)}^4
    \mathord{\mathbb E} \|\psi^{W+I}\|_{H^1(\Lambda)}^{8\varepsilon}
    \right]^{1/4}
    \left[ \mathord{\mathbb E} \|I\|_{H^1(\rho^{1/2})}^2 \right]^{1/2}.
\end{split}
\end{equation}
Again by Lemmas~\ref{lem:estimate-psi-phi42},~\ref{lemma:apriori}, and~\ref{wick-power-estimate}
this is at most
\begin{equation}
C_\varepsilon \lambda q (1 + |\log m|^p) \!
    \left[ 1
    + \left(\frac{\mathcal B_{q,\lambda,m,\varepsilon}}{(1 - (1+\kappa) m^2)}\right)^{4\varepsilon/(1-\varepsilon)}
                                                                                                    
    \right]
    \left(\frac{\mathcal B_{q,\lambda,m,\varepsilon}}{(1 - (1+\kappa) m^2)}\right)^{1/2}.
\end{equation}
Taking $\varepsilon$ small enough and combining these bounds gives the statement.

\label{thm:heat kernel bounds}
The two-dimensional heat kernel $J_t$ satisfies the following estimates:
\begin{enumerate}
\item[(a)] $\displaystyle \left\|\int_0^\infty J_t f_t \mathop{}\!\mathrm d t\right\|_{\mathcal C^1(\Lambda)}
    \lesssim \sup_{t \geq 0}\, \langle t \rangle^{1/2+\varepsilon} \|f_t\|_{L^\infty(\Lambda)}$,
    where $\varepsilon > 0$.
\item[(b)] $\displaystyle \|J_t f\|_{L^\infty(\Lambda)} \lesssim \langle t \rangle^{-1} \|f\|_{L^\infty(\Lambda)}$.
\end{enumerate}
Let us denote by~$C_t(x,y)$ and $C^{\ast 2}_t(x,y)$ the convolution kernels
of~$J_t$ and $J_t^2$.
They satisfy:
\begin{enumerate}
\item[(c)] $\|C_t\|_{L^1(\Lambda)} \lesssim \langle t \rangle^{-1}$ independently of~$m$.
\item[(d)] $\|C^{\ast 2}_t\|_{L^1(\Lambda)} \lesssim m^{-2} \langle t \rangle^{-2}$.
\end{enumerate}

This statement has essentially been proved
in~\cite{barashkov_stochastic_2022,gubinelli_fbsde_2026,bauerschmidt_logsobolev_2021,bauerschmidt_maximum_2022}.
We reprove it here in the context of lattice approximations and uniformly in the volume,
while also tracking the dependence on~$\lambda$ and~$m$.
We will opt for the method of Gubinelli and Meyer~\cite{gubinelli_fbsde_2026}.

By~\cite[Lemma~2.5]{gubinelli_fbsde_2026},
there exists an optimal~$h\in \mathbb{H}_a$ in Theorem~\ref{thm:boue-dupuis}
that satisfies almost surely the equation
\begin{equation}\label{eq:FBDSE}
h_{t}
=- \lambda\beta J_{t} \mathord{\mathbb E} [ \mathord{\mathopen: \sin (\beta W_{\infty} + \beta I_{\infty}[h]) \mathclose:} \mid \mathcal{F}_t ] .
\end{equation}
One can show \cite{barashkov_variational_2023,gubinelli_fbsde_2026}
that then $\mu_{\beta} = \operatorname{Law}(W+I)$.
Note that in this case we do not need to pass to the space $\overline{\mathcal{X}}$
to ensure existence of the minimizer.

Denoting $X_t = W_t + I_t$, we can rewrite~\eqref{eq:FBDSE} as a system.
For any $F\in C^2(\mathbb R_+ \times \mathbb R^\Lambda, \mathbb R^\Lambda)$,
we set $R_t = \lambda\beta \mathord{\mathbb E} [ \mathord{\mathopen: \sin (\beta W_{\infty} + \beta I_{\infty}[h]) \mathclose:} \mid \mathcal{F}_t ]
    - F_t (W_t+I_t(h))$.
As discussed in~\cite[Section~2.3]{gubinelli_fbsde_2026},
$R_t$ then solves the system
\begin{equation}
\begin{split}
R_t &= \mathord{\mathbb E} \left[ \int^{\infty}_t H_s (X_s) + \mathrm{D} F_s (X_s) J^2_s R_s \mathop{}\!\mathrm d s
    \,\middle|\, \mathcal{F}_t \right]\!,\\
H_t &\coloneqq \partial_t F_t + \frac{1}{2} \operatorname{Tr} (J^2_t \mathrm{D}^2 F_t)
    -\frac{1}{2} \mathrm{D} \langle F_t, J^2_t F_t \rangle_{L^2 (\Lambda)} .
\end{split}
\end{equation}

In our setting we will set
\begin{equation}
F_t (\varphi) = \lambda \beta e^{\frac{\beta^2 c_{t}}{2}} \sin (\beta \varphi),
\end{equation}
where $c_t = \mathord{\mathbb E} [W_{t}(0)^2] = \log(t \wedge \delta^2)/4\pi + O(1)$.
(This estimate follows by adapting~\cite[Appendix~A]{gubinelli_fbsde_2026} to the periodic setup.)
It can be checked that this satisfies
\begin{equation}
\partial_t F_t + \frac{1}{2} \text{Tr} (J^2_t \mathrm{D}^2 F_t) = 0, \qquad
F_{\infty} (\varphi) = \lambda \beta \mathord{\mathopen: \sin (\beta \varphi) \mathclose:}.
\end{equation}
In addition we have, with the notation $\lambda_{t}=\lambda e^{\frac{\beta^2 c_{t}}{2}}$, the identity
\begin{equation}
\langle F_t, J^2_t F_t \rangle_{L^2 (\Lambda)}
= \lambda^2_t \beta^2 \iint \sin (\beta \varphi) (x) C^{\ast 2}_t (x - y) \sin (\beta \varphi) (y) \mathop{}\!\mathrm d x\mathop{}\!\mathrm d y,
\end{equation}
where $C^{\ast 2}_t$ is as in Lemma~\ref{thm:heat kernel bounds}.
(For brevity we replace the sums over $\Lambda$ with integrals in convolutions.)
So taking the gradient we have
\begin{equation}
H_t = -\frac 1 2 \mathrm{D} \langle F_t, J^2_t F_t \rangle_{L^2 (\Lambda)}
= -\lambda^2_t \beta^3
    \iint \cos (\beta \varphi) (x) C^{\ast 2}_t (x - y) \sin (\beta \varphi) (y) \mathop{}\!\mathrm d x\mathop{}\!\mathrm d y.
\end{equation}
Observe that this implies the estimate
\begin{equation} \label{eq:estimate-bilinear}
\begin{split}
\|\mathrm{D} \langle F_t, J^2_t F_t \rangle_{L^2 (\Lambda)}\|_{L^{\infty}(\Lambda)}
&\leq \lambda^2_t \beta^3 \|C^{\ast 2}_t\|_{L^1}\\
&\leq \frac{1}{m^2} \beta^3 \lambda^2_t t^{-2}\\
&\leq \frac{1}{m^2} \lambda^2 \beta^3 \langle t \rangle^{-1 - \varepsilon},
\end{split}
\end{equation}
where $\varepsilon$ is taken small enough.
In particular $R$ satisfies the bound
\begin{equation}
\begin{split}
\|R_t\|_{L^{\infty}(\mathord{\mathbb P}, L^{\infty} (\Lambda))}
&\leq \frac{C \lambda^2}{m^2} \beta^3 + \lambda \beta^2
    \int_t^\infty \langle s \rangle^{\beta^2 / 4 \pi}
        \|J^2_s R_s\|_{L^{\infty}(\mathord{\mathbb P}, L^{\infty} (\Lambda))} \mathop{}\!\mathrm d s\\
&\leq \frac{C \lambda^2}{m^2} \beta^3 + \frac{\lambda \beta^2}{m^2}
    \int_t^\infty \langle s \rangle^{- 2 - \varepsilon + \beta^2 / 4 \pi}
        \|R_s\|_{L^{\infty}(\mathord{\mathbb P}, L^{\infty} (\Lambda))} \mathop{}\!\mathrm d s.
\end{split}
\end{equation}
From Grönwall's lemma we conclude
\begin{equation}
\|R_t\|_{L^{\infty} (\mathord{\mathbb P}, L^{\infty} (\Lambda))}
\leq \frac{C \lambda^2}{m^2} \beta^3 \exp \left( \frac{C \lambda \beta^2}{m^2} \right)
\eqqcolon \tilde{A}(m,\lambda,\beta).
\end{equation}
This, \eqref{eq:estimate-bilinear}, and the heat kernel bounds
together imply that
\begin{equation}
\begin{split}
\|I_{\infty}(h)\|_{\mathcal C^1}
&= \left\|\int_0^\infty  J^2_t (F_t(W_t+I_t(h))+R_t) \mathop{}\!\mathrm d t\right\|_{\mathcal C^1}\\
&\leq \sup_{t\geq 0} \left( \langle t \rangle^{1/2+\varepsilon}
    \|J_t (F_t(W_t+I_t(h))+R_t)\|_{L^\infty} \right)\\
&\leq C \sup_{t\geq 0}\left( \lambda \beta \langle t \rangle^{1/2+\varepsilon+ \beta^2/8\pi-1}
    + \langle t \rangle^{-1/2+\varepsilon} \|R_{t}\|_{L^{\infty}}\right)\\
&\leq  C \lambda \beta + \tilde{A}(m,\lambda,\beta).
\end{split}
\end{equation}
We can dissolve $\beta < 4\pi$ into the implicit constant,
and this expression then gives our $A(m,\lambda)$.

\label{lemma:bottom-product}
Let $W$ be a Gaussian free field
and $I \in L^{\infty} (\mathord{\mathbb P}, \mathcal C^{1 - \varepsilon}(\Lambda))$
such that $\|I\|_{L^{\infty} (\mathord{\mathbb P},\, \mathcal C^{1 - \varepsilon})} \leq  A(m,\lambda)$.
Then 
\[
\begin{split}
&\mathrel{\phantom{=}} \inf_{\|\psi\|_{L^2} = 1}
    -\lambda \beta^2 \delta^2 \sum_{x \in \Lambda} \chi \mathord{\mathopen: \cos(\beta W + \beta I) \mathclose:} \psi^2
    + m^2 \delta^2 \sum_{x \in \Lambda} \psi^2
    + \frac{\delta^2}{2} \sum_{x \in \Lambda} |\nabla_{\delta} \psi|^2\\
&\geq -  \frac{\lambda A(m,\lambda)^{2-\varepsilon'}}{m^{2-\varepsilon'}}
   \left[ \|\mathord{\mathopen: \sin (\beta W) \mathclose:}\|^{2 - \varepsilon'}_{\mathcal C^{- \beta^2 / 4 \pi - \varepsilon} (\rho)}+\|\mathord{\mathopen: \cos (\beta W) \mathclose:}\|^{2 - \varepsilon'}_{\mathcal C_{\delta}^{- \beta^2 / 4 \pi - \varepsilon} (\rho)}\right]
\end{split}
\]
for $\varepsilon' > 0$ small enough.

We may write
\begin{equation}
\begin{split}
&\mathrel{\phantom{=}} \delta^2 \sum_{x \in \Lambda} \chi  \mathord{\mathopen: \cos (\beta W + \beta I) \mathclose:} \psi^2\\
&= -\delta^2 \sum_{x \in \Lambda} \chi \mathord{\mathopen: \sin (\beta W) \mathclose:} \sin (\beta I) \psi^2
    + \delta^2 \sum_{x \in \Lambda} \chi \mathord{\mathopen: \cos (\beta W) \mathclose:} \cos (\beta I) \psi^2.
\end{split}
\end{equation}
We will now estimate the first term.
The second term is analogous.
We decompose the term as two paraproducts
\begin{equation}\label{eq:bottom-product paraproducts}
\begin{split}
&\mathrel{\phantom{=}} \delta^2 \sum_{x \in \Lambda} \chi \mathord{\mathopen: \sin (\beta W) \mathclose:} \sin (\beta I) \psi^2\\
&= \delta^2 \sum_{x \in \Lambda} \chi [\psi \succeq \mathord{\mathopen: \sin (\beta W) \mathclose:}] \sin (\beta I) \psi
    + \delta^2 \sum_{x \in \Lambda} \chi [\psi \prec \mathord{\mathopen: \sin (\beta W) \mathclose:}] \sin (\beta I) \psi.
\end{split}
\end{equation}
Since we have assumed $\beta^2 / 4 \pi < 1$, we can estimate for $\varepsilon$ small that
\begin{equation}
\begin{split}
&\mathrel{\phantom{=}} \delta^2 \sum_{x \in \Lambda} \chi [\psi \succeq \mathord{\mathopen: \sin (\beta W) \mathclose:}] \sin (\beta I) \psi\\
&\leq \|\psi\|_{H^{1 - \varepsilon}(\Lambda)}
    \|\mathord{\mathopen: \sin (\beta W) \mathclose:}\|_{\mathcal C^{- \beta^2 / 4 \pi - \varepsilon} (\rho)}
    \|\sin (\beta I) \psi\|_{L^2(\Lambda)}\\
&\leq \|\psi\|_{H^{1 - \varepsilon}(\Lambda)}
    \|\mathord{\mathopen: \sin (\beta W) \mathclose:}\|_{\mathcal C^{- \beta^2 / 4 \pi - \varepsilon} (\rho)}.
\end{split}
\end{equation}
Now estimating the second term of~\eqref{eq:bottom-product paraproducts},
\begin{equation}
\begin{split}
&\mathrel{\phantom{=}} \delta^2 \sum_{x \in \Lambda} \chi (\psi \prec \mathord{\mathopen: \sin (\beta W) \mathclose:}) \sin (\beta I) \psi\\
&\leq \|\psi\|_{L^2(\Lambda)}
    \|\mathord{\mathopen: \sin (\beta W) \mathclose:}\|_{\mathcal C^{- \beta^2 / 4 \pi - \varepsilon} (\rho)}
    \|\sin(\beta I) \psi\|_{H^{1 - \varepsilon}(\Lambda)}\\
&\lesssim \|\mathord{\mathopen: \sin (\beta W) \mathclose:}\|_{\mathcal C^{-\beta^2 / 4 \pi - \varepsilon} (\rho)}
    \|\psi\|_{H^{1 - \varepsilon}(\Lambda)}
    \|I\|_{\mathcal C^{1 - \varepsilon}(\Lambda)}\\
&\lesssim A(m,\lambda) \|\mathord{\mathopen: \sin (\beta W) \mathclose:}\|_{\mathcal C^{- \beta^2 / 4 \pi - \varepsilon} (\rho)}
    \|\psi\|_{H^{1 - \varepsilon}(\Lambda)},
\end{split}
\end{equation}
where the estimate
$\|\sin(\beta I)\|_{\mathcal C^{1-\varepsilon}} \lesssim \|I\|_{\mathcal C^{1-\varepsilon}}$
follows by Lipschitz continuity.
Collecting the terms we obtain the bound
\begin{equation}
\lambda \beta^2 \left| \delta^2 \sum_{x \in \Lambda} \chi \psi^2 \mathord{\mathopen: \sin (\beta W) \mathclose:} \sin (\beta I) \right|
\leq \lambda C A(m,\lambda)
    \|\mathord{\mathopen: \sin (\beta W) \mathclose:}\|_{\mathcal C^{- \beta^2 / 4 \pi - \varepsilon} (\rho)}
    \|\psi\|^{1 - \varepsilon}_{H^1}.
\end{equation}
Thus by Young's inequality we get 
\begin{equation}
\begin{split}
&\mathrel{\phantom{=}} \lambda \beta^2 \delta^2 \sum_{x \in \Lambda} \chi \psi^2 \mathord{\mathopen: \cos (\beta W + \beta I) \mathclose:}
    + m^2 \delta^2 \sum_{x \in \Lambda} \psi^2
    + \frac{\delta^2}{2} \sum_{x \in \Lambda} |\nabla_{\delta} \psi|^2\\
&\gtrsim - \frac{\lambda A(m,\lambda)^{2-\varepsilon'}}{m^{2-\varepsilon'}} \left(
    \|\mathord{\mathopen: \sin (\beta W) \mathclose:}\|^{2 - \varepsilon'}_{\mathcal C^{- \beta^2 / 4 \pi - \varepsilon}(\rho)}
    + \|\mathord{\mathopen: \cos (\beta W) \mathclose:}\|^{2 - \varepsilon'}_{\mathcal C^{- \beta^2 / 4 \pi - \varepsilon}(\rho)} \right).
\end{split}
\end{equation}

\label{lem:estimate-sin-product}
For $\beta^2 < 4\pi$, we can bound
\[
\begin{split}
&\mathrel{\phantom{=}}
\|\mathord{\mathopen: \cos (\beta W + \beta I) \mathclose:}\|_{\mathcal C^{- \beta^2 / 4\pi - \varepsilon} (\rho)}
+ \|\mathord{\mathopen: \sin (\beta W + \beta I) \mathclose:}\|_{\mathcal C^{- \beta^2 / 4\pi - \varepsilon} (\rho)}\\
&\lesssim \left(
    \|\mathord{\mathopen: \cos (\beta W) \mathclose:}\|_{\mathcal C^{- \beta^2 / 4\pi - \varepsilon}(\rho)}
    + \|\mathord{\mathopen: \sin (\beta W) \mathclose:}\|_{\mathcal C^{- \beta^2 / 4\pi - \varepsilon}(\rho)}
    \right) (1 + \|I\|_{H^1(\mathbb T^2)}).
\end{split}
\]

By the usual trigonometric identity and Definition~\ref{def:wick},
\begin{equation}
\mathord{\mathopen: \cos (\beta W + \beta I) \mathclose:}
= \mathord{\mathopen: \cos (\beta W) \mathclose:} \cos (\beta I) - \mathord{\mathopen: \sin (\beta W) \mathclose:} \sin (\beta I).
\end{equation}
We again use a paraproduct decomposition (Theorem~\ref{thm:besov paraproducts}).
First,
\begin{equation}
\|\mathord{\mathopen: \cos(\beta W) \mathclose:} \prec \cos(\beta I)\|_{\mathcal C^{-\beta^2/4\pi - \epsilon}(\rho)}
\lesssim 
    \|\mathord{\mathopen: \cos(\beta W) \mathclose:}\|_{\mathcal C^{-\beta^2/4\pi - \epsilon}(\rho)}
    \|\cos(\beta I)\|_{L^\infty(\mathbb T^2)},
\end{equation}
where the second factor is trivially bounded.
The same estimate holds for the opposite paraproduct as well.
The resonant term is then estimated with
\begin{equation}
\begin{split}
\|\mathord{\mathopen: \cos(\beta W) \mathclose:} \odot \cos(\beta I)\|_{\mathcal C^{-\beta^2/4\pi - \epsilon}(\rho)}
&\lesssim \|\mathord{\mathopen: \cos(\beta W) \mathclose:} \odot \cos(\beta I)\|_{H^{1 - \beta^2/4\pi - \epsilon}(\rho)}\\
&\lesssim \|\mathord{\mathopen: \cos(\beta W) \mathclose:}\|_{\mathcal C^{- \beta^2/4\pi - \epsilon}(\rho)}
    \|\cos(\beta I)\|_{H^1(\mathbb T^2)}
\end{split}
\end{equation}
and the chain rule.
The estimate on the sine is analogous.

\label{lem:estimate-sin-moment}
There exists $p<\infty$ such that for any $q>0$ the following estimate holds:
\begin{equation*}
\log \mathord{\mathbb E} \exp \left(
    q \|\mathord{\mathopen: \sin (\beta W) \mathclose:}\|^{2 - \varepsilon'}_{\mathcal C^{-\beta^2/4\pi-\varepsilon}(\rho)}
  + q \|\mathord{\mathopen: \cos (\beta W) \mathclose:}\|^{2 - \varepsilon'}_{\mathcal C^{-\beta^2/4\pi-\varepsilon}(\rho)} \right)
\lesssim \left(\frac{q}{(m\wedge1)^{2+\beta^2/2\pi}}\right)^p.
\end{equation*}

To show exponential tails we apply the Bou{\'e}--Dupuis formula to obtain
\begin{equation}\label{eq:estimate-sin-moment bd}
\begin{split}
&\mathrel{\phantom{=}} \log \mathord{\mathbb E} \exp \left(
    q \|\mathord{\mathopen: \sin (\beta W) \mathclose:}\|^{2 - \varepsilon'}_{\mathcal C^{-\beta^2/4\pi-\varepsilon}(\rho)}
  + q \|\mathord{\mathopen: \cos (\beta W) \mathclose:}\|^{2 - \varepsilon'}_{\mathcal C^{-\beta^2/4\pi-\varepsilon}(\rho)} \right)\\
&= \inf_{h \in \mathbb{H}_a} \mathord{\mathbb E} \left[
    q \|\mathord{\mathopen: \sin (\beta W + \beta I[h]) \mathclose:}\|^{2-\varepsilon'}_{\mathcal C^{-\beta^2/4\pi-\varepsilon}(\rho)}
    + q \|\mathord{\mathopen: \cos (\beta W+\beta I[h]) \mathclose:}\|^{2 - \varepsilon'}_{\mathcal C^{-\beta^2/4\pi-\varepsilon}(\rho)}
    + \frac{1}{2} \int^{\infty}_0 \!\! \|h_t\|^2_{L^2} \mathop{}\!\mathrm d t \right]\!.
\end{split}
\end{equation}
We now apply Lemma~\ref{lem:estimate-sin-product} to estimate the expectation from below by
\begin{equation}
-C q \! \left[
    \|\mathord{\mathopen: \cos (\beta W) \mathclose:}\|_{\mathcal C^{- \beta^2 / 4\pi - \varepsilon}(\rho)}
    + \|\mathord{\mathopen: \sin (\beta W) \mathclose:}\|_{\mathcal C^{- \beta^2 / 4\pi - \varepsilon}(\rho)}
\right]^{2 - \varepsilon'} \!\! (1+ \|I[h]\|_{H^1})^{2 - \varepsilon'}
+ \frac{1}{2} \int^{\infty}_0 \!\! \|h_t\|^2_{L^2} \mathop{}\!\mathrm d t.
\end{equation}
The definition of $J_s$ and Lemma~\ref{thm:besov hs norm} imply
\begin{equation}
\begin{split}
(m^2 \wedge 1) \|I[h]\|_{H^1}^2
&\simeq \sum_{k \in \hat\Lambda} (m^2 \wedge 1) (1 + |k|^2) \left[ \int_0^\infty
    \frac 1 t \exp\!\left( -\frac{m^2 + |k|^2}{2t} \right) \hat h(t, k) \mathop{}\!\mathrm d t \right]\\
&\leq \sum_{k \in \hat\Lambda} ((m^2 \wedge 1) + |k|^2) \left[ \int_0^\infty
    \frac{1}{t^2} \exp\!\left( -\frac{m^2 + |k|^2}{t} \right) \mathop{}\!\mathrm d t \right]
    \!\left[ \int_0^\infty \hat h(t, k)^2 \mathop{}\!\mathrm d t \right]\\
&\leq \int_0^\infty \|h_t\|_{L^2}^2 \mathop{}\!\mathrm d t.
\end{split}
\end{equation}
We therefore obtain by Young's inequality that
\begin{equation}
\begin{split}
\eqref{eq:estimate-sin-moment bd}
&\geq -C [q / (m^2 \wedge 1)]^{2/\varepsilon'} \mathord{\mathbb E} \left[ 1
        + \|\mathord{\mathopen: \cos (\beta W) \mathclose:}\|_{\mathcal C^{- \beta^2 / 4\pi - \varepsilon}(\rho)}
        + \|\mathord{\mathopen: \sin (\beta W) \mathclose:}\|_{\mathcal C^{- \beta^2 / 4\pi - \varepsilon}(\rho)}
    \right]^{4/\varepsilon'}\\
&\qquad{} - \frac 1 4 (m^2 \wedge 1) \|I[h]\|_{H^1}^2
    + \frac 1 2 \int_0^\infty \|h_t\|_{L^2}^2 \mathop{}\!\mathrm d t\\
&\geq -C \left( \frac{q}{(m \wedge 1)^{2+\beta^2/2\pi}} \right)^{2/\varepsilon'},
\end{split}
\end{equation}
where we evaluated the expectation with Lemma~\ref{moment-gff-sine}.

\label{thm:sine-gordon finished}
There exists $p \in (1,\infty)$, independent of $m$, $\lambda$, and $\beta$,
such that $Q(u)$ defined by~\eqref{eq:Q} satisfies
\[
\log \int \exp\left(\frac{4}{\sigma}Q(u)\right) \mathop{}\!\mathrm d\mu_{\beta}(u)
\lesssim \left(
    \frac{4\lambda A(m,\lambda)^{2-\varepsilon'}}
        {\sigma (m \wedge 1)^{4-\varepsilon'+\beta^2/2\pi}}
    \right)^p .
\]

By Theorem~\ref{prop:coupling} we may write
\begin{equation}
\int \exp \left( \frac{4}{\sigma} Q (u) \right) \mathop{}\!\mathrm d \mu_\beta (u)
= \mathord{\mathbb E} \left[ \exp \left( \frac{4}{\sigma} Q (W + I) \right) \right],
\end{equation}
and by Lemma~\ref{lemma:bottom-product} we have
\begin{equation}
|Q (W + I)|
\leq \frac{\lambda A(m,\lambda)^{2-\varepsilon'}}{(m\wedge1)^{2-\varepsilon'}} \left[
    \|\mathord{\mathopen: \sin(\beta W) \mathclose:}\| ^{2 - \varepsilon'}_{\mathcal C^{- \beta^2 / 4 \pi - \varepsilon} (\rho)}
    \|\mathord{\mathopen: \cos(\beta W) \mathclose:}\| ^{2 - \varepsilon'}_{\mathcal C^{- \beta^2 / 4 \pi - \varepsilon} (\rho)}
    \right],
\end{equation}
from which we can conclude by Lemma~\ref{lem:estimate-sin-moment}.

Set $h = (1 - \operatorname{\mathrm{\Delta}}_\delta)^{1 / 2} \varphi$.
Leaving the renormalization term $2\lambda^2a_{\delta} \varphi^2$ in~$\mathcal A_\delta(W)(\varphi)$
aside for the moment,
and utilizing $\|\varphi\|_{L^2 (\Lambda)} = 1$, we are left with
\begin{equation}\label{eq:3d-form-wick-square simple hessian}
12\lambda\delta^3 \sum_{x \in \Lambda} \mathord{\mathopen: W^2 \mathclose:} \varphi^2
    + \delta^3 \sum_{x \in \Lambda} h^2
    - (1 - m^2).
\end{equation}
The last term is bounded below by $-1$ uniformly in $m^2>0$.
We can rewrite the first term as
\begin{equation}\label{eq:3d-form-wick square first}
\begin{split}
&\mathrel{\phantom{=}} 12\lambda \langle \mathord{\mathopen: W^2 \mathclose:} \varphi, \varphi \rangle_{L^2}\\
&= 12\lambda \langle \mathord{\mathopen: W^2 \mathclose:} \succ \varphi, \varphi \rangle_{L^2}
    + 12\lambda \langle \mathord{\mathopen: W^2 \mathclose:} \circ \varphi, \varphi \rangle_{L^2}
    + 12\lambda \langle \mathord{\mathopen: W^2 \mathclose:} \prec \varphi, \varphi \rangle_{L^2}\\
&= 24\lambda \langle \mathord{\mathopen: W^2 \mathclose:} \succ \varphi, \varphi \rangle_{L^2}
    + 12\lambda \mathfrak{C}_1 (W, \varphi),
\end{split}
\end{equation}
where
\begin{equation}
\mathfrak{C}_1 (W, \varphi) \coloneqq
    \langle \mathord{\mathopen: W^2 \mathclose:} \prec \varphi, \varphi \rangle_{L^2}
    + \langle \mathord{\mathopen: W^2 \mathclose:} \circ \varphi, \varphi \rangle_{L^2}
    - \langle \mathord{\mathopen: W^2 \mathclose:} \succ \varphi, \varphi \rangle_{L^2}.
\end{equation}
The commutator $\mathfrak{C}_1 (\mathord{\mathopen: W^2 \mathclose:}, \varphi)$ is estimated in
Lemma~\ref{first-commutator} below.
We then remove the first term in~\eqref{eq:3d-form-wick square first}
with an ansatz for $h$.
We observe that
\begin{equation}
\langle \mathord{\mathopen: W^2 \mathclose:} \succ \varphi, \varphi \rangle_{L^2}
= \langle (1 - \operatorname{\mathrm{\Delta}}_\delta)^{- 1 / 2} (\mathord{\mathopen: W^2 \mathclose:} \succ \varphi), h \rangle_{L^2}.
\end{equation}
Set
\begin{equation}
Z_\varphi \coloneqq (1-\operatorname{\mathrm{\Delta}}_\delta)^{-1/2}(\mathord{\mathopen: W^2 \mathclose:}\succ\varphi),
\end{equation}
and define $w$ by $h=-12\lambda Z_\varphi+w$.
Then
\begin{equation}
\begin{split}
\|h\|_{L^2}^2
&= -24\lambda\langle Z_\varphi,w\rangle_{L^2}
    + 144\lambda^2 \|Z_\varphi\|_{L^2}^2 + \|w\|_{L^2}^2\\
&= -24\lambda\langle Z_\varphi,h\rangle_{L^2}
    - 144\lambda^2 \|Z_\varphi\|_{L^2}^2 + \|w\|_{L^2}^2.
\end{split}
\end{equation}
Thus the first two terms in~\eqref{eq:3d-form-wick-square simple hessian} equal
\begin{equation}
24\lambda\langle\mathord{\mathopen: W^2 \mathclose:}\succ\varphi,\varphi\rangle_{L^2}
    + \|h\|_{L^2}^2
= -144\lambda^2 \|Z_\varphi\|_{L^2}^2
    + \|w\|_{L^2}^2
    + 12\lambda \mathfrak{C}_1 (W, \varphi).
\end{equation}

We next analyze $\|Z_\varphi\|_{L^2}^2$.
Recall the notation
$A_\delta^{\circ2}=(1-\operatorname{\mathrm{\Delta}}_\delta)^{-1/2}\mathord{\mathopen: W^2 \mathclose:}$ and set
\begin{equation}
\mathfrak C_2(\mathord{\mathopen: W^2 \mathclose:},\varphi)
= Z_\varphi - A_\delta^{\circ2} \succ \varphi.
\end{equation}
The commutator estimate \cite[Proposition~A.2]{allez_continuous_2015}
gives for $\alpha \in [0,1-\varepsilon)$ that
\begin{equation}
\|\mathfrak C_2(\mathord{\mathopen: W^2 \mathclose:},\varphi)\|_{H^{\alpha}}
\lesssim \|\mathord{\mathopen: W^2 \mathclose:}\|_{\mathcal C^{-1-\varepsilon}} \|\varphi\|_{H^{\alpha+\varepsilon}}.
\end{equation}
Hence
\begin{equation}\label{eq:3d-form-wick-square a norm}
\|Z_\varphi\|_{L^2}^2
= \|A_\delta^{\circ2} \succ\varphi\|_{L^2}^2
    + \|\mathfrak C_2(\mathord{\mathopen: W^2 \mathclose:},\varphi)\|_{L^2}^2
    + 2\langle A_\delta^{\circ2} \succ\varphi, \mathfrak C_2(\mathord{\mathopen: W^2 \mathclose:},\varphi) \rangle_{L^2},
\end{equation}
and using the estimate for $\mathfrak{C}_2$ with Besov interpolation,
\begin{equation}
\begin{split}
&\mathrel{\phantom{=}} \|\mathfrak C_2(\mathord{\mathopen: W^2 \mathclose:},\varphi)\|_{L^2}^2
    + 2\langle A_\delta^{\circ2} \succ\varphi,  \mathfrak C_2(\mathord{\mathopen: W^2 \mathclose:},\varphi) \rangle_{L^2}\\
&\lesssim \|\mathord{\mathopen: W^2 \mathclose:}\|_{\mathcal C^{-1-\varepsilon}}^2 \|\varphi\|_{H^\varepsilon}^2
    + \|(1-\operatorname{\mathrm{\Delta}}_\delta)^{-1/2}\mathord{\mathopen: W^2 \mathclose:} \succ \varphi\|_{H^{-2\varepsilon}}
        \|\mathfrak C_2(\mathord{\mathopen: W^2 \mathclose:},\varphi)\|_{H^{2\varepsilon}}\\
&\lesssim \|\mathord{\mathopen: W^2 \mathclose:}\|_{\mathcal C^{-1-\varepsilon}}^2
        \|\varphi\|_{H^{1-\varepsilon}}^{2\varepsilon/(1-\varepsilon)}.
\end{split}
\end{equation}
To deal with the first term of~\eqref{eq:3d-form-wick-square a norm}
we observe that by Lemma~\ref{c3} below,
\begin{equation}
\mathfrak{C}_3(\mathord{\mathopen: W^2 \mathclose:}, \varphi) \coloneqq
\left\|((1 - \operatorname{\mathrm{\Delta}}_\delta)^{- 1 / 2} \mathord{\mathopen: W^2 \mathclose:} \succ \varphi)^2
    - ((1 - \operatorname{\mathrm{\Delta}}_\delta)^{- 1 / 2} \mathord{\mathopen: W^2 \mathclose:})^2 \varphi^2\right\|_{L^1}
\end{equation}
is bounded by $C \|\mathord{\mathopen: W^2 \mathclose:}\|^2_{\mathcal C^{-1-\varepsilon}}
    \|\varphi\|_{H^{1-\varepsilon}}^{3\varepsilon/(1-\varepsilon)}$.

At this point, we have bounded~\eqref{eq:3d-form-wick square first} from below by
\begin{equation}
-144\lambda^2 \|((1 - \operatorname{\mathrm{\Delta}}_\delta)^{- 1 / 2} \mathord{\mathopen: W^2 \mathclose:}) \varphi\|_{L^2}^2
    + \|w\|_{L^2}^2
    - 1
    - C(\lambda + \lambda^2) (1 + \|\mathord{\mathopen: W^2 \mathclose:}\|_{\mathcal C^{- 1 - \varepsilon}}^2) \Bigl[ 
        1 + \|\varphi\|^{1 + 4 \varepsilon}_{H^{1 - \varepsilon}} \Bigr].
\end{equation}
Let us now add back the renormalization term $2\lambda^2 a_\delta \varphi^2$
to cancel the divergence of the first term.
They combine as
\begin{equation}
-144\lambda^2 \delta^3 \sum_{x \in \Lambda}
    \left(((1 - \operatorname{\mathrm{\Delta}}_\delta)^{-1/2}\mathord{\mathopen: W^2 \mathclose:})^{2} -\frac{a_{\delta}}{72}\right) \varphi^2.
\end{equation}
With the notation of Definition~\ref{rem:hessian-coefficients}, we can estimate
\begin{equation}
\lambda^2 \left|\delta^3 \sum_{x \in \Lambda}
    \left(A_\delta^{\circ2} -\frac{a_{\delta}}{72}\right) \varphi^2\right|
\lesssim \lambda^2 \|W^{2\diamond2}\|_{\mathcal C^{-\varepsilon}} \|\varphi\|_{H^{\varepsilon}}^2
\lesssim \lambda^2 \|W^{2\diamond2}\|_{\mathcal C^{-\varepsilon}} \|\varphi\|_{H^{1-\varepsilon}}^{3\varepsilon}.
\end{equation}
Therefore we have showed
\begin{equation}\label{eq:anderson-proper}
\mathcal{A}_{\delta}(W)(\varphi) \geq \|w\|_{L^2}^2 + R(W, \varphi) - 1,
\end{equation}
where the remainder satisfies  
\begin{equation}
|R (W, \varphi)|
\leq C (\lambda + \lambda^2) (1 + \|W^{2 \diamond 2}\|_{\mathcal C^{- \varepsilon}}
        + \|\mathord{\mathopen: W^2 \mathclose:}\|^2_{\mathcal C^{- 1 - \varepsilon}})
    (1 + \|\varphi\|^{1+4\varepsilon}_{{H^{1 - \varepsilon}} }).
\end{equation}
  
Let us abbreviate
\begin{equation}
X \coloneqq 1 + \|W^{2\diamond2}\|_{\mathcal C^{-\varepsilon}}
    + \|\mathord{\mathopen: W^2 \mathclose:}\|_{\mathcal C^{-1-\varepsilon}}^2.
\end{equation}
We also use the definitions of~$h$ and~$w$, paraproduct estimates,
and the assumption $\|\varphi\|_{L^2} = 1$, to observe
\begin{equation}
\begin{split}
\|\varphi\|_{{H^{1 - \varepsilon}} }
&\leq 12\lambda \|(1 - \operatorname{\mathrm{\Delta}}_\delta)^{- 1 / 2} (\mathord{\mathopen: W^2 \mathclose:} \succ \varphi)\|_{H^{- \varepsilon}}
    + \|w\|_{L^2}\\
&\leq C \lambda \|\mathord{\mathopen: W^2 \mathclose:}\|_{\mathcal C^{- 1 - \varepsilon}}
    \|\varphi\|_{L^2}
    + \|w\|_{L^2}\\
&\leq C \lambda \|\mathord{\mathopen: W^2 \mathclose:}\|_{\mathcal C^{- 1 - \varepsilon}}
    + \|w\|_{L^2}.
\end{split}
\end{equation}
Therefore the remainder can be further estimated as
\begin{equation}
R(W,\varphi)+\|w\|_{L^2}^2
\geq \|w\|_{L^2}^2
    -C(\lambda+\lambda^2)X
    (1 + \|\mathord{\mathopen: W^2 \mathclose:}\|_{\mathcal C^{-1-\varepsilon}}^{1+4\varepsilon}
        + \|w\|_{L^2}^{1+4\varepsilon}).
\end{equation}
As we assumed $\lambda \leq 1$, the final term can be estimated with Young's inequality as
\begin{equation}
-C_\varepsilon \lambda \left[
    X (1 + \|\mathord{\mathopen: W^2 \mathclose:}\|_{\mathcal C^{-1-\varepsilon}}^{1+4\varepsilon})
    + X^{r_\varepsilon} \right]
- \frac \lambda 2 \|w\|_{L^2}^2,
\quad\text{where } r_\varepsilon = \frac{2}{1 - 4\varepsilon}.
\end{equation}
The stochastic quantities $X$ and $\|\mathord{\mathopen: W^2 \mathclose:}\|_{\mathcal C^{-1-\varepsilon}}$
have moments of all orders; see~\cite[Section~4.1]{gubinelli_pde_2021}
for the corresponding lattice stochastic estimates.
Hence we can replace the stochastic terms with a random variable $\Xi$
that has uniform-in-$\delta$ bounds on moments.

Finally, by definition
\begin{equation}
\|w\|_{L^2}^2
\geq \|\varphi\|_{H^{1-\varepsilon}}^2
    -144\lambda^2\|\mathord{\mathopen: W^2 \mathclose:}\|_{\mathcal C^{-1-\varepsilon}}^2.
\end{equation}
Absorbing the last stochastic term into $\Xi$ proves the estimate.

In the first term we have by duality,
the paraproduct estimate (Lemma~\ref{thm:besov paraproducts}),
and interpolation
\begin{equation}
\langle \mathord{\mathopen: W^2 \mathclose:} \prec \varphi, \varphi \rangle_{L^2 (\Lambda)}
\lesssim \|\mathord{\mathopen: W^2 \mathclose:}\|_{\mathcal C^{- 1 - \varepsilon}}
    \|\varphi\|_{H^{1 - \varepsilon}}
    \|\varphi\|_{H^{3\varepsilon}}
\lesssim (1 + \|\mathord{\mathopen: W^2 \mathclose:}\|_{\mathcal C^{- 1 - \varepsilon}})
    \|\varphi\|^{1 + 4 \varepsilon}_{H^{1 - \varepsilon}}.
\end{equation}
For the second term we apply \cite[Lemma~A.6]{gubinelli_semilinear_2020} to get
\begin{equation}
\begin{split}
\left|\langle\mathord{\mathopen: W^2 \mathclose:}\circ\varphi,\varphi\rangle_{L^2}
    - \langle\mathord{\mathopen: W^2 \mathclose:}\succ\varphi,\varphi\rangle_{L^2}\right|
&\lesssim
    \|\mathord{\mathopen: W^2 \mathclose:}\|_{\mathcal C^{-1-\varepsilon}}
    \|\varphi\|_{H^{1-\varepsilon}}
    \|\varphi\|_{H^{3\varepsilon}}\\
&\lesssim
    \left(1+\|\mathord{\mathopen: W^2 \mathclose:}\|_{\mathcal C^{-1-\varepsilon}}\right)
    \|\varphi\|_{H^{1-\varepsilon}}^{1+4\varepsilon}.
\end{split}
\end{equation}

With $A_\delta^{\circ2}=(1-\operatorname{\mathrm{\Delta}}_\delta)^{-1/2}\mathord{\mathopen: W^2 \mathclose:}$, we note that
\begin{equation}
(A_\delta^{\circ2})^2\varphi^2 - (A_\delta^{\circ2} \succ \varphi)^2
= (A_\delta^{\circ2} \preccurlyeq \varphi)^2
    + 2(A_\delta^{\circ2} \succ \varphi)(A_\delta^{\circ2} \preccurlyeq \varphi).
\end{equation}
Now the second term can be estimated by
\begin{equation}
\begin{split}
&\mathrel{\phantom{=}} \left|\delta^3 \sum_{x \in \Lambda}
    ((1 - \operatorname{\mathrm{\Delta}}_\delta)^{- 1 / 2} \mathord{\mathopen: W^2 \mathclose:} \succ \varphi)
    ((1 - \operatorname{\mathrm{\Delta}}_\delta)^{- 1 / 2} \mathord{\mathopen: W^2 \mathclose:} \preccurlyeq \varphi)\right|\\
&\lesssim \|(1 - \operatorname{\mathrm{\Delta}}_\delta)^{- 1 / 2} \mathord{\mathopen: W^2 \mathclose:} \succ \varphi\|_{H^{-2\varepsilon}}
    \|(1 - \operatorname{\mathrm{\Delta}}_\delta)^{- 1 / 2} \mathord{\mathopen: W^2 \mathclose:} \preccurlyeq \varphi\|_{H^{2\varepsilon}}\\
&\lesssim \|(1 - \operatorname{\mathrm{\Delta}}_\delta)^{- 1 / 2} \mathord{\mathopen: W^2 \mathclose:}\|_{\mathcal C^{- \varepsilon}}
    \|\varphi\|_{L^2}
    \|(1 -\operatorname{\mathrm{\Delta}}_\delta)^{- 1 / 2} \mathord{\mathopen: W^2 \mathclose:}\|_{\mathcal C^{-\varepsilon}}
    \|\varphi\|_{H^{3 \varepsilon}}\\
&\lesssim \|\mathord{\mathopen: W^2 \mathclose:}\|^2_{\mathcal C^{- 1 - \varepsilon}}
    \|\varphi\|_{H^{3 \varepsilon}}
    \|\varphi\|_{L^2}.
\end{split}
\end{equation}
The first term can be bounded analogously, and we can conclude.

\label{lem:lower-bound}
With $\Xi$ as in Proposition~\ref{3d-form-wick-square} and $\beta \geq 0$ we have
\[
\beta \mathcal{A} (W + W^{[3]} + K) (\psi)
\geq \beta ((1-\lambda/2) \|\psi\|^2_{H^{1 - \varepsilon}} - 1)
    - \frac{1}{8} \|\psi\|^2_{H^{1 - \varepsilon}}
    - \mathcal{B}^1 (W, \lambda, m, \beta) - \mathcal{E} (K),
\]
where we assume $\|\psi\|_{L^2} = 1$ and denote for some $\varepsilon' > 0$ small
\begin{align*}
\mathcal B^1(W,\lambda,m,\beta)
    &\coloneqq C\Bigl(\lambda\beta\|WW^{[3]}\|_{\mathcal C^{-1/2-\varepsilon}}\Bigr)^3
    +C\Bigl(\beta\lambda^{3/4}
        \|W\|_{\mathcal C^{-1/2-\varepsilon}}\Bigr)^{8/(1-\varepsilon')}\\
    &\quad +C\Bigl(\beta\lambda^{7/8}m^{-1/2}
    \|W\|_{\mathcal C^{-1/2-\varepsilon}}\Bigr)^{16/(1-\varepsilon')}
    +\beta C_\varepsilon \lambda^{1-2\varepsilon}(1+\lambda)^{r_\varepsilon}\Xi.
\end{align*}

We have already shown in Lemma~\ref{3d-form-wick-square} that
\begin{equation}
\beta\mathcal A(W)(\psi)
\geq \beta (1-\lambda/2) \|\psi\|_{H^{1-\varepsilon}}^2
    - \beta C_\varepsilon \lambda^{1-2\varepsilon} (1+\lambda)^{r_\varepsilon}\Xi
    - \beta.
\end{equation}
By definition of $\mathcal A$ we get
\begin{equation}
\begin{split}
\mathcal{A} (W + W^{[3]} + K) (\psi) - \mathcal{A} (W) (\psi)
&=24\lambda\delta^3 \sum_{x \in \Lambda} W W^{[3]} \psi^2
    +24\lambda\delta^3 \sum_{x \in \Lambda} W K\psi^2\\
&\quad+12\lambda\delta^3 \sum_{x\in\Lambda}(W^{[3]}+K)^2\psi^2,
\end{split}
\end{equation}
and since we are deriving a lower bound,
we can ignore the last term as non-negative.
The first term is estimated, after multiplying by $\beta$,
with duality and interpolation as
\begin{equation}
\begin{split}
24\lambda \beta \left|\delta^3 \sum_{x \in \Lambda} W W^{[3]} \psi^2\right|
&\leq 24 \lambda \beta \|W W^{[3]}\|_{\mathcal C^{- 1 / 2 - \varepsilon}}
    \|\psi^2\|_{B^{1 / 2 + \varepsilon}_{1,1}}\\
&\leq 24 \lambda \beta \|W W^{[3]}\|_{\mathcal C^{- 1 / 2 - \varepsilon}}
    \|\psi\|^{1 + \varepsilon}_{H^{1 - \varepsilon}}\\
&\leq C_\kappa (\lambda \beta \|W W^{[3]}\|_{\mathcal C^{- 1 / 2 - \varepsilon}})^3
    + \kappa \|\psi\|^2_{H^{1 - \varepsilon}}.
\end{split}
\end{equation}

For the second term, the fractional Leibniz rule
(see e.g.~\cite{benyi_fractional_2024}) gives the following estimate,
where the positive parameters $\varepsilon_i$ record arbitrarily
small, interdependent, losses in the Sobolev embeddings:
\begin{equation}\label{eq:estiamte-3d-KW-1}
\begin{split}
&\mathrel{\phantom{=}}
    24 \lambda \beta \left|\delta^3 \sum_{x \in \Lambda} W K \psi^2\right|\\
&\lesssim \lambda\beta \|W\|_{\mathcal C^{-1/2-\varepsilon}}
    \|K \psi^2\|_{B^{1/2+\varepsilon}_{1,1}}\\
&\lesssim \lambda\beta \|W\|_{\mathcal C^{-1/2-\varepsilon}} \Bigl(
    \|K\|_{L^4} \|\psi^2\|_{W^{1/2+\varepsilon, 4/3}}
    + \|K\|_{W^{1/2+\varepsilon, 8/3-\varepsilon_1}}
        \|\psi^2\|_{L^{8/5+\varepsilon_2}}
\Bigr)\\
&\lesssim \lambda\beta \|W\|_{\mathcal C^{-1/2-\varepsilon}} \Bigl(
    \|K\|_{L^4} \|\psi\|_{W^{1/2+\varepsilon, 8/3}} \|\psi\|_{L^{8/3}}
    + \|K\|_{W^{1/2+\varepsilon, 8/3-\varepsilon_1}}
        \|\psi\|_{L^{16/5+\varepsilon_3}}^2
\Bigr).
\end{split}
\end{equation}
We now estimate the first term as
\begin{equation}\label{eq:estiamte-3d-KW-2}
\begin{split}
&\mathrel{\phantom{=}} \lambda\beta \|W\|_{\mathcal C^{-1/2-\varepsilon}}
    \|K\|_{L^4} \|\psi\|_{W^{1/2+\varepsilon, 8/3}} \|\psi\|_{L^{8/3}}\\
&\lesssim \lambda\beta \|W\|_{\mathcal C^{-1/2-\varepsilon}}
    \|K\|_{L^4} \|\psi\|_{H^{7/8+\varepsilon}} \|\psi\|_{H^{3/8}}\\
&\leq \lambda\beta \|W\|_{\mathcal C^{-1/2-\varepsilon}}
    \|K\|_{L^4} \|\psi\|_{H^{1-\varepsilon}}^{5/4+\varepsilon_4}\\
&\leq C_\kappa (\beta \lambda^{3/4} \|W\|_{\mathcal C^{-1/2-\varepsilon}})^{8/(1-4\varepsilon_4)}
    + \kappa \lambda \|K\|_{L^4}^4
    + \kappa \|\psi\|_{H^{1-\varepsilon}}^2.
\end{split}
\end{equation}
In the second term we estimate
\begin{equation}\label{eq:estiamte-3d-KW-3}
\begin{split}
&\mathrel{\phantom{=}} \lambda\beta \|W\|_{\mathcal C^{-1/2-\varepsilon}}
    \|K\|_{W^{1/2+\varepsilon, 8/3-\varepsilon_1}}
    \|\psi\|_{L^{16/5+\varepsilon_3}}^2\\
&\lesssim \lambda\beta \|W\|_{\mathcal C^{-1/2-\varepsilon}}
    \|K\|_{L^4}^{1/2}
    \|K\|_{H^{1-\varepsilon}}^{1/2}
    \|\psi\|_{H^{1-\varepsilon}}^{9/8+\varepsilon_5}\\
&= \lambda^{7/8}\beta m^{-1/2} \|W\|_{\mathcal C^{-1/2-\varepsilon}}
    \lambda^{1/8} \|K\|_{L^4}^{1/2}
    m^{1/2} \|K\|_{H^{1-\varepsilon}}^{1/2}
    \|\psi\|_{H^{1-\varepsilon}}^{9/8+\varepsilon_5}\\
&\leq C_\kappa (\lambda^{7/8}\beta m^{-1/2} \|W\|_{\mathcal C^{-1/2-\varepsilon}})^{16/(1-8\varepsilon_5)}
    + \kappa \lambda \|K\|_{L^4}^{4}
    + \kappa m^2 \|K\|_{H^{1-\varepsilon}}^2
    + \kappa \|\psi\|_{H^{1-\varepsilon}}^2.
\end{split}
\end{equation}
This requires that $\varepsilon$ is small enough compared to $\varepsilon_1$.
Setting $\kappa = 1/24$ gives the stated lower bound.

Let $\varphi$ solve
\begin{equation}\label{eq:competitor fixpoint}
\varphi = -12\lambda (1 - \operatorname{\mathrm{\Delta}}_\delta)^{-1} \mathrm P_{>N} (\mathord{\mathopen: W^2 \mathclose:}\succ \varphi) + 1.
\end{equation}
This equation can be solved by fixed point in~$\mathcal C^{1 -  \varepsilon}(\Lambda)$
whenever $N \gg \|\mathord{\mathopen: W^2 \mathclose:}\|^p_{\mathcal C^{- 1 -  \varepsilon}}$ for $p$ sufficiently large,
and one gets
\begin{equation}
\|\varphi\|_{\mathcal C^{1 - \varepsilon}}
\leq C (1 + \|\mathord{\mathopen: W^2 \mathclose:}\|^p_{\mathcal C^{- 1 - \varepsilon}}).
\end{equation}
Then we have $\|\varphi\|_{L^2} \geq 1$, since by Jensen's
inequality and the fact that the high-frequency projection has zero mean,
\begin{equation}
\|\varphi\|_{L^2}
\geq \delta^3 \sum_{x \in \Lambda} \varphi(x)
= 12\lambda \delta^3 \underbrace{\sum_{x \in \Lambda}
        (1 - \operatorname{\mathrm{\Delta}}_\delta)^{-1} \mathrm P_{>N} (\mathord{\mathopen: W^2 \mathclose:}\succ \varphi)(x)}_{=0}
    {} + \delta^3 \sum_{x \in \Lambda} 1.
\end{equation}

Set $h=(1-\operatorname{\mathrm{\Delta}}_\delta)^{1/2}\varphi$ and, as in the proof of Lemma~\ref{3d-form-wick-square},
\begin{equation}
w = h+12\lambda(1-\operatorname{\mathrm{\Delta}}_\delta)^{-1/2} (\mathord{\mathopen: W^2 \mathclose:}\succ\varphi).
\end{equation}
Applying $(1-\operatorname{\mathrm{\Delta}}_\delta)^{1/2}$ to the fixed-point equation~\eqref{eq:competitor fixpoint} gives
\begin{equation}
w = 1 + 12\lambda(1-\operatorname{\mathrm{\Delta}}_\delta)^{-1/2} \mathrm P_{\leq N}(\mathord{\mathopen: W^2 \mathclose:}\succ\varphi).
\end{equation}
Hence the low-frequency multiplier estimate and the paraproduct estimate
yield
\begin{equation}
\|w\|_{L^2}
\leq 1+C\lambda N^{2\varepsilon}
    \|\mathord{\mathopen: W^2 \mathclose:}\|_{\mathcal C^{-1-\varepsilon}} \|\varphi\|_{L^2}
\leq C\left(1+\|\mathord{\mathopen: W^2 \mathclose:}\|_{\mathcal C^{-1-\varepsilon}}\right)^p,
\end{equation}
where we increase~$p$ if necessary.
Finally, the identity~\eqref{eq:anderson-proper} and its remainder estimate give
\begin{equation}
|\mathcal A(W)(\varphi)|
\leq \|w\|_{L^2}^2 + |R(W,\varphi)| + 1
\leq C\left(1+\|W^{2\diamond2}\|_{\mathcal C^{-\varepsilon}}
    + \|\mathord{\mathopen: W^2 \mathclose:}\|_{\mathcal C^{-1-\varepsilon}}\right)^p.
\end{equation}
This upper bound is preserved when we normalize $\varphi$ to have unit $L^2$~norm.

We begin by deriving an upper bound on $\mathcal{A} (W + W^{[3]} + K) (\psi)$.
If we plug $\varphi$ from Lemma~\ref{lem:competitor} into the functional, we get
\begin{equation}
\begin{split}
\mathcal{A} (W + W^{[3]} + K) (\varphi)
&= \mathcal{A}(W) (\varphi)
    + 24\lambda\delta^3 \sum_{x \in \Lambda} W W^{[3]} \varphi^2\\
&\quad + 24\lambda\delta^3 \sum_{x \in \Lambda} W K \varphi^2
    + 12\lambda\delta^3 \sum_{x \in \Lambda} (W^{[3]} + K)^2 \varphi^2.
\end{split}
\end{equation}
By Lemma~\ref{lem:competitor},
\begin{equation}
\mathcal A(W)(\varphi)
\leq C\left(1+\|W^{2\diamond2}\|_{\mathcal C^{-\varepsilon}}
    + \|\mathord{\mathopen: W^2 \mathclose:}\|_{\mathcal C^{-1-\varepsilon}}\right)^p,
\end{equation}
and the same upper bound holds for $\|\varphi\|_{\mathcal C^{1-\varepsilon}}$.
The remaining terms satisfy
\begin{equation}
\begin{split}
\left|\langle WW^{[3]},\varphi^2\rangle\right|
    &\lesssim \|WW^{[3]}\|_{\mathcal C^{-1/2-\varepsilon}}
    \|\varphi\|_{\mathcal C^{1-\varepsilon}}^2,\\
|\langle WK,\varphi^2\rangle|
    &\lesssim \|K\|_{H^{1/2+\varepsilon}}
    \|W\|_{\mathcal C^{-1/2-\varepsilon}}
    \|\varphi\|_{\mathcal C^{1-\varepsilon}}^2,\\
\|(W^{[3]}+K)\varphi\|_{L^2}^2
    &\lesssim \|\varphi\|_{\mathcal C^{1-\varepsilon}}^2
    \left(\|W^{[3]}\|_{L^2}^2 + \|K\|_{L^2}^2\right).
\end{split}
\end{equation}
Define
\begin{equation}
\mathcal R_W
= 1 + \|\mathord{\mathopen: W^2 \mathclose:}\|_{\mathcal C^{-1-\varepsilon}}
    + \|W^{2\diamond2}\|_{\mathcal C^{-\varepsilon}}.
\end{equation}
Also set
\begin{equation}
\mathcal S_{W,K}
= 1 + \|WW^{[3]}\|_{\mathcal C^{-1/2-\varepsilon}}
    + \|W^{[3]}\|_{L^2}^2
    + \|K\|_{L^2}^2
    + \|K\|_{H^{1/2+\varepsilon}} \|W\|_{\mathcal C^{-1/2-\varepsilon}}.
\end{equation}
Combining these estimates gives
\begin{equation}
\mathcal A(W+W^{[3]}+K)(\varphi)
\leq \mathcal R_W^{2p} \mathcal S_{W,K}.
\end{equation}
We now use Lemma~\ref{lem:lower-bound}, choosing $\beta_0 = 16/\eta$.
The lemma gives
\begin{equation}
\begin{split}
&\mathrel{\phantom{=}} \mathcal{A} (W + W^{[3]} + K) (\psi^{W + I})\\
&\geq \left(\frac 1 4 \|\psi\|^2_{H^{1 - \varepsilon}} - 1\right)
- \frac{1}{8\beta_0} \|\psi\|^2_{H^{1 - \varepsilon}}
- \beta_0^{-1} \mathcal{B}^1 (W, \lambda, m, \beta_0) - \beta_0^{-1}\mathcal{E} (K)\\
&\geq \frac{1}{8}\|\psi^{W + I}\|^2_{H^{1 - \varepsilon}}
    - \beta_0^{-1}\mathcal{B}^1 (W, \lambda, m,\beta_0)
    - \beta_0^{-1}\mathcal{E} (K)
    - 1.
\end{split}
\end{equation}
Thus we obtain
\begin{equation}
\frac 1 8 \|\psi^{W+I}\|_{H^{1-\varepsilon}}^2
\leq \mathcal R_W^{2p} \mathcal S_{W,K}
    + \frac{\eta}{16} \mathcal{B}^1 (W, \lambda, m, 16/\eta)
    + \frac{\eta}{16} \mathcal{E} (K)
    + 1.
\end{equation}
Finally, we can use Young's inequality to estimate $\mathcal R_W^{2p} \mathcal S_{W,K}$
with $\tfrac C \eta \mathcal R_W^{4p} + \tfrac{\eta}{16} \mathcal E(K)$.
This finishes the proof.

Let $\psi^u$ be a normalized ground state of $\mathcal A(u)$. Since
\begin{equation}
Q(u) = -\inf_{\|\psi\|_{L^2}=1} \mathcal A(u)(\psi),
\end{equation}
the Feynman--Hellmann formula gives, keeping in mind the decomposition $u=W+W^{[3]}+K$, that
\begin{equation}\label{eq:Q-gradient}
\begin{split}
\langle\nabla Q(u),K\rangle
&= -24\lambda\delta^3 \sum_{x\in\Lambda} u(x)K(x)(\psi^u(x))^2.\\
&= -24\lambda\delta^3 \sum_{x\in\Lambda} (W+W^{[3]}+K)(x)K(x)(\psi^u(x))^2\\
&\geq -24\lambda\delta^3 \sum_{x\in\Lambda} (W+W^{[3]})(x)K(x)(\psi^u(x))^2.
\end{split}
\end{equation}
We now apply the same reasoning as in the proof of Lemma~\ref{lem:lower-bound},
more precisely equations~\eqref{eq:estiamte-3d-KW-1},
\eqref{eq:estiamte-3d-KW-2}, and~\eqref{eq:estiamte-3d-KW-3},
as well as those inequalities with $W$ replaced by $W^{[3]}$ to get 
\begin{equation}\label{eq:tilt-pairing}
\begin{split}
&\mathrel{\phantom{=}} q \langle\nabla Q(u),K\rangle  \\ 
&\geq  -C_\eta (\lambda^{7/8}q m^{-1/2} (\|W\|_{\mathcal C^{-1/2-\varepsilon}}+\|W^{[3]}\|_{\mathcal C^{-1/2-\varepsilon}}))^{16/(1-8\varepsilon_5)}
- \eta \mathcal{E}(K)
- \eta \|\psi\|_{H^{1-\varepsilon}}^2\\
&\geq -\eta \mathcal{E}(K)- \mathcal{B}^2_{\eta}(W,\lambda,m)
    -C_\eta [\lambda^{7/8}q m^{-1/2} (\|W\|_{\mathcal C^{-1/2-\varepsilon}}+\|W^{[3]}\|_{\mathcal C^{-1/2-\varepsilon}})]^{16/(1-\varepsilon)},
\end{split}
\end{equation}
where in the last line we have applied Proposition~\ref{bound-3d-ground}.
We set
\begin{equation}
\mathcal{B}^4_{\eta}(W,\lambda,m,q)
\coloneqq C_\eta [\lambda^{7/8}\beta m^{-1/2} (\|W\|_{\mathcal C^{-1/2-\varepsilon}}
    +\|W^{[3]}\|_{\mathcal C^{-1/2-\varepsilon}})]^{16/(1-8\varepsilon)}.
\end{equation}

We now derive the equation satisfied by $K$, which  follows from the decomposition $K=u-W-W^{[3]}$. Writing
$\mathrm L_\delta=\partial_t+m^2-\operatorname{\mathrm{\Delta}}_\delta$ and
$\mathrm P_0 = \mathrm{Id} - \mathrm P_{\geq1}$, we obtain
\begin{equation}
\mathrm L_\delta K
    + 4\lambda\bigl(\mathord{\mathopen: u^3 \mathclose:}-\mathord{\mathopen: W^3 \mathclose:}\bigr)
    + 2\lambda^2 a_\delta u
    - q\nabla Q(u)
= \sqrt2\, \mathrm P_0\xi.
\label{eq:K-equation}
\end{equation}
Using Itô's formula we obtain
\begin{equation}
0 = \frac12 \frac{\mathop{}\!\mathrm d}{\mathop{}\!\mathrm d t} \mathord{\mathbb E} \|K\|_{L^2}^2
= \mathord{\mathbb E}\langle F_K,K\rangle_{L^2} - \operatorname{Tr}_{L^2}(P_0),
\end{equation}
where
\begin{equation}
F_K = (m^2-\operatorname{\mathrm{\Delta}}_\delta)K
    + 4\lambda\bigl(\mathord{\mathopen: u^3 \mathclose:}-\mathord{\mathopen: W^3 \mathclose:}\bigr)
    + 2\lambda^2a_\delta u-q\nabla Q(u).
\end{equation}
Since $\mathrm P_0$ projects onto the normalized constant mode,
$\operatorname{Tr}_{L^2}(P_0)=1$.
Proposition~\ref{prop-gub-hov} and~\eqref{eq:tilt-pairing} therefore give
\begin{equation}
(1-\eta)\mathord{\mathbb E}\mathcal E(K)
\leq 1+\mathord{\mathbb E}\!\left[ \mathcal B^3(W,\lambda,m,q)
    + \mathcal B^2_{\eta}(W,\lambda,m)
    + \mathcal B^4_{\eta}(W,\lambda,m)\right].
\label{inequality-energy}
\end{equation}
Finally observe that if $\|\psi\|_{L^2}=1$,
we have $\|\psi\|^2_{H^{1-\varepsilon}}\geq 1$, so
\begin{equation}
q \left((1-\lambda/2) \|\psi\|^2_{H^{1-\varepsilon}}-1\right)
\geq -\frac{\lambda q}{2}.
\end{equation}
Thus we obtain, applying Lemma~\ref{lem:lower-bound},
\begin{equation}
\begin{split}
q\int Q(u)\,\mathop{}\!\mathrm d\nu^{qQ}(u)
&= -q\,\mathord{\mathbb E}\inf_{\|\psi\|_2=1}\mathcal A
       (W+W^{[3]}+K)(\psi)\\
&\leq C\, \mathord{\mathbb E}\!\left[1 +\lambda q/2 +\mathcal E(K)
    + \mathcal B^1(W,\lambda,m,q)\right],
\end{split}
\end{equation}
where the inequality is the negative of the lower bound in Lemma~\ref{lem:lower-bound}.
Using the energy estimate~\eqref{inequality-energy} and the asserted uniform moments of~$\mathcal B^i$,
this is the required \emph{upper} bound on $q\int Q\,d\nu^{qQ}$.
It can then be fed into Lemma~\ref{lem:hairer-steele} to bound $Z^{qQ}$, and obtain $\mathcal{R}$.

Finally by examining each $\mathcal B^i$, we observe that $\mathcal R$ indeed satisfies
\begin{equation}
\sup_{q, m, \lambda}  \mathcal{R}(q,m,\lambda) < \infty
\end{equation}
in the regime $\lambda\lesssim m^{3}$, $m\leq 1$, $q\lesssim m^{-2}$.

We first use Theorem~\ref{thm:besov properties}
to go from $\mathcal C^{-\kappa}$ to $B_{p,p}^{-\kappa/2}$ for $p$ large enough.
We then use hypercontractivity, translation invariance, and Wick formula
to estimate
\begin{equation}
\begin{split}
\mathord{\mathbb E} \|\mathord{\mathopen: W^k \mathclose:}\|_{B_{p,p}^{-\kappa}(\rho)}^p
&\lesssim \sum_{j \geq -1} 2^{-pj\kappa} [\mathord{\mathbb E} (\Delta_j \mathord{\mathopen: W^k \mathclose:}(0))^2]^{p/2} \int \rho(x)^p \mathop{}\!\mathrm d x\\
&\lesssim \sum_{j \geq -1} 2^{-pj\kappa} \int K_j(-x) K_j(-y) \mathord{\mathbb E} [\mathord{\mathopen: W^k \mathclose:}(x) \, \mathord{\mathopen: W^k \mathclose:}(y)]^{p/2} \mathop{}\!\mathrm d x \mathop{}\!\mathrm d y\\
&\lesssim \sum_{j \geq -1} 2^{-pj\kappa} \int K_j(-x) K_j(-y) G(x,y)^{pk/2} \mathop{}\!\mathrm d x \mathop{}\!\mathrm d y,
\end{split}
\end{equation}
where $K_j$ are the kernels of the Littlewood--Paley blocks $\Delta_j$,
and $G$ is the Green's function of the free field.

The Green's function is of order $\log(m |x-y|)$ near the diagonal
and rapidly decaying away from it~\cite[Chapter~7]{glimm_quantum_1981}.
On the other hand, the kernels $K_j$ are uniformly bounded in $L^1$ norm
and of order $2^j$ in $L^\infty$ norm.
Therefore we can interpolate
\begin{equation}
\|K_j\|_{L^{q/(q-1)}} \lesssim 2^{j/q}.
\end{equation}
These considerations imply that
\begin{equation}
\mathord{\mathbb E} \|\mathord{\mathopen: W^k \mathclose:}\|_{B_{p,p}^{-\kappa}(\rho)}^p
\lesssim \sum_{j \geq -1} 2^{-pj\kappa} (|\log(m)|^{pk/2} + 2^{j/q}).
\end{equation}
By choosing $q$ large enough, we get the claim.

We express $W = W_{\infty} = \int^{\infty}_0 J_t \mathop{}\!\mathrm d B_t$,
where $J_t$ is as in Section~\ref{sec:sine-gordon measure}
and $B_t$ is an $L^2 (\Lambda)$ cylindrical Brownian motion.
It follows from the Itô formula that
$\mathord{\mathopen: \sin (\beta W_\infty) \mathclose:} = \beta \int_0^\infty \mathord{\mathopen: \cos (\beta W_t) \mathclose:} \mathop{}\!\mathrm d W_t$.
Its quadratic variation is given by
\begin{equation}
\begin{split}
&\mathrel{\phantom{=}}
\beta^2 \left\langle \int^{\infty}_0 \mathord{\mathopen: \cos (\beta W_t) \mathclose:} (x) \mathop{}\!\mathrm d W_t (x),
    \int^{\infty}_0 \mathord{\mathopen: \cos (\beta W_t) \mathclose:} (y) \mathop{}\!\mathrm d W_t (y)
\right\rangle\\
& = \beta^2 \int_0^\infty C^{\ast 2}_t (x - y) \mathord{\mathopen: \cos (\beta W_t) (x) \mathclose:}
    \mathord{\mathopen: \cos (\beta W_t) (y) \mathclose:} \mathop{}\!\mathrm d t.
\end{split}
\end{equation}
Here $C^{\ast 2}_t$ is the convolution kernel of $J_t^2$,
as in Section~\ref{sec:sine-gordon measure}.

Using this we can deduce that the Littlewood--Paley blocks satisfy
\begin{equation}
\begin{split}
&\mathrel{\phantom{=}} \langle (\Delta_j \mathord{\mathopen: \sin (\beta W) \mathclose:}) (z) \rangle\\
&= \beta^2 \int^{\infty}_0 \!\!\! \iint C^{\ast 2}_t(x - y) K_j (x - z) K_j (y - z)
    \mathord{\mathopen: \cos(\beta W_t) (x) \mathclose:} \mathord{\mathopen: \cos (\beta W_t) (y) \mathclose:} \mathop{}\!\mathrm d x \mathop{}\!\mathrm d y \mathop{}\!\mathrm d t\\
&\leq \beta^2 \int^{\infty}_0 \!\!\! \iint C^{\ast 2}_t(x - y)
    |K_j (x- z) K_j (y - z)| \langle t \rangle^{\beta^2 / 2 \pi} \mathop{}\!\mathrm d x \mathop{}\!\mathrm d y \mathop{}\!\mathrm d t\\
&= \beta^2 \int^{\infty}_0 \!\!\! \iint C^{\ast 2}_t(x - y)
    |K_j (x) K_j (y)| \langle t \rangle^{\beta^2 / 2 \pi} \mathop{}\!\mathrm d x \mathop{}\!\mathrm d y \mathop{}\!\mathrm d t,
\end{split}
\end{equation}
where $K_j$ is again the convolution kernel of the block $\Delta_j$.

Now it is not hard to show that (see~\cite[Appendix~A]{bauerschmidt_logsobolev_2021})
\begin{equation}
\begin{split}
\int_0^\infty C^{\ast 2}_t(x - y) \langle t \rangle^{\beta^2 / 2 \pi} \mathop{}\!\mathrm d t
&\lesssim \int_0^\infty e^{- \frac{|x - y|^2}{2 t} - m t} \langle t \rangle^{\beta^2 / 2 \pi} \mathop{}\!\mathrm d t\\
&\lesssim \frac{1}{|x-y|^{\beta^2 / 2 \pi}} + m^{\beta^2 / 2 \pi}.
\end{split}
\end{equation}
Now for $2 / q > \beta^2 / 4 \pi$ we can estimate
\begin{equation}
\begin{split}
&\mathrel{\phantom{=}} \iint
    \left( \frac{1}{| x - y |^{\beta^2 / 2 \pi}} + m^{\beta^2 / 2\pi} \right)
    |K_j (x) K_j (y)| \langle t \rangle^{\beta^2 / 2 \pi} \mathop{}\!\mathrm d x \mathop{}\!\mathrm d y\\
&\lesssim \|K_j\|^2_{L^q} + m^{-\beta^2 / 2 \pi} \|K_j\|^2_{L^1}.
\end{split}
\end{equation}
From this we can conclude by applying the Burkholder--Davis--Gundy inequality:
for $\kappa > \beta^2 / 4 \pi$ and $p$ large enough, we have
\begin{equation}
\begin{split}
&\mathrel{\phantom{=}} \mathord{\mathbb E} \|\mathord{\mathopen: \sin (\beta W) \mathclose:}\|^p_{\mathcal C^{-\kappa}(\rho)}\\
&\lesssim \mathord{\mathbb E} \|\mathord{\mathopen: \sin (\beta W) \mathclose:}\|^p_{B_{p, p}^{- \kappa + \varepsilon / 2}(\rho)}\\
&\leq \sum 2^{- j p (\kappa + \varepsilon / 2)}
    \mathord{\mathbb E} \|\Delta_j \mathord{\mathopen: \sin (\beta W) \mathclose:}\|_{L^p (\rho)}^p\\
&\leq \sum 2^{- j p (\kappa + \varepsilon / 2)}
    \mathord{\mathbb E} |\Delta_j \mathord{\mathopen: \sin (\beta W) \mathclose:} (0) |^p\\
&\lesssim \sum 2^{- j p (\kappa + \varepsilon / 2)}
    (\mathord{\mathbb E} \langle \Delta_j \mathord{\mathopen: \sin (\beta W) \mathclose:} (0) \rangle)^{p / 2}\\
&\lesssim \sum 2^{- j p (\kappa + \varepsilon / 2)}
    (\|K_j\|^p_{L^q} + m^{-p\beta^2 / 4 \pi} \|K_j\|^p_{L^1})\\
&\lesssim (m \wedge 1)^{-p \beta^2 / 4 \pi}.
\end{split}
\end{equation}
The proof for the $\cos$ is analogous.
